local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[1205] = {id=1205,name="Deadmire",level=15,requiredLevel=15,faction="horde",expansion=9,zoneID=15,mapID=70,description="Deadmire is an ancient crocolisk in Dustwallow marsh . And it is his time to die. Old bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver. Yet now he lives in constant, maddening pain. You must end the life of this noble creature, . You must lead Deadmire to peace.",starts={{npcID=3441,x=0.612,y=0.806,mapID=88}},ends={{npcID=3441,x=0.612,y=0.806,mapID=88}},coords={x=0.612,y=0.806,source="quest_giver",mapID=70},questType="standard"},
[3721] = {id=3721,name="An OOX of Your Own",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=5287,mapID=210,starts={{npcID=7406,x=0.43,y=0.72,mapID=210}},ends={{npcID=7406,x=0.43,y=0.72,mapID=210}},coords={x=0.43,y=0.72,source="quest_giver",mapID=210},questType="standard"},
[6365] = {id=6365,name="Meats to Orgrimmar",level=1,requiredLevel=1,faction="horde",expansion=9,zoneID=14,mapID=1,description="I have some choice cuts of meat that I want to send to a friend. Her name is Gryshka, the innkeeper in Orgrimmar. Will you deliver the meat for me? The fastest way to Orgrimmar is on a wind rider. Take the meats to the Razor Hill wind rider master, Burok , and speak with him about transport to Orgrimmar.",starts={{npcID=3489,x=0.506,y=0.578,mapID=10},{npcID=3881,x=0.508,y=0.428,mapID=1}},ends={{npcID=3615,x=0.486,y=0.586,mapID=10},{npcID=41140,x=0.53,y=0.436,mapID=1}},coords={x=0.506,y=0.578,source="quest_giver",mapID=1},questType="standard"},
[6608] = {id=6608,name="You Too Good.",level=15,requiredLevel=35,faction="horde",expansion=9,zoneID=15,mapID=70,description="Lumak no can teach no more. You too good! Find Lumak friend, Nat Pagle . Is human but no eat! Is Lumak friend! Nat teach you fish gooder. You find Nat in Dustwallow Marsh, south of Humie town, Thermorosomethinglikedat. Nat probably fishing. Go now!",starts={{npcID=3332,x=0.666,y=0.416,mapID=85}},ends={{npcID=12919,x=0.586,y=0.602,mapID=70}},coords={x=0.666,y=0.416,source="quest_giver",mapID=70},questType="standard"},
[8193] = {id=8193,name="Grand Prize",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=5287,mapID=210,starts={{npcID=15077,x=0.414,y=0.73,mapID=210}},ends={{npcID=15077,x=0.414,y=0.73,mapID=210}},coords={x=0.414,y=0.73,source="quest_giver",mapID=210},questType="standard"},
[11412] = {id=11412,name="There and Back Again",level=1,requiredLevel=1,faction="horde",expansion=9,zoneID=14,mapID=1,description="Am I glad you're here. We are in big trouble! There's been a brew accident on the road to Bladefist Bay, and kegs are no longer being transported. You gotta get us that brew! I'll put you on one of my racing rams and you follow the road to Bladefist Bay. Once you get near him he'll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant. For now, all we want are 3 kegs. Do a good job and maybe we'll have another job for you.",starts={{npcID=24497,x=0.426,y=0.178,mapID=1}},ends={{npcID=24497,x=0.426,y=0.178,mapID=1}},coords={x=0.426,y=0.178,source="quest_giver",mapID=1},questType="standard"},
[24625] = {id=24625,name="Consort of the Sea Witch",level=1,requiredLevel=1,faction="horde",expansion=9,zoneID=6453,mapID=463,description="I been investigatin' our corrupted Bloodtalons troubles and I think I've found da source. A lone naga. He was holdin' a red orb aloft over our hatchlings and I could see dem... changin'. I'm certain he tinks his thievery and spellcastin' have gone unnoticed, so ya should be able ta catch him unawares. Kill dis naga and bring me back dat vile orb - you'll be findin' him to da northwest, at Zalazane's Fall.",starts={{npcID=37987,x=0.634,y=0.952,mapID=1},{npcID=37987,x=0.456,y=0.85,mapID=463}},ends={{npcID=37987,x=0.634,y=0.952,mapID=1},{npcID=37987,x=0.456,y=0.85,mapID=463}},coords={x=0.634,y=0.952,source="quest_giver",mapID=463},questType="standard"},
[26763] = {id=26763,name="Venture Company Mining",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=33,mapID=50,description="If I'm going to repair this pot, I'm going to need reagents. And to get them, you're going to have to do an eensy little bit of killing. I hope you don't mind. Those dastardly Venture Company geologists have been collecting some tumbled crystals that will suffice for what I need. You'll find them around their Base Camp, on the other side of Lake Nazferiti, to the east. I don't care what you have to do to get them.",starts={{npcID=773,x=0.436,y=0.23,mapID=50}},ends={{npcID=773,x=0.436,y=0.23,mapID=50}},coords={x=0.436,y=0.23,source="quest_giver",mapID=50},questType="standard"},
[26926] = {id=26926,name="Victory, For Now",level=15,requiredLevel=15,faction="horde",expansion=9,zoneID=85,mapID=18,description="The Forsaken are victorious, and our forces are still strong. Military strategy dictates that we attack the Alliance now, while they are recovering and unaware. I have other plans, however... We will wait. We attack Thassarian and his troops when the time is right. In the meantime, speak with Rhonda Molver and take a flight to the Bulwark, on the Plaguelands' western border. High Executor Derrington will give you your next assignment. You will hear from me when you are needed again in Andorhal.",starts={{npcID=44452,x=0.47,y=0.638,mapID=22}},ends={{npcID=10837,x=0.832,y=0.69,mapID=18}},coords={x=0.47,y=0.638,source="quest_giver",mapID=18},questType="standard"},
[26992] = {id=26992,name="Agony Abounds",level=5,requiredLevel=5,faction="horde",expansion=9,zoneID=130,mapID=21,description="You have no doubt heard about the incident that transpired at the Wrath Gate in Northrend, yes? Due to those unfortunate events we are strictly forbidden from using the strain of life-shattering blight that we finally perfected. Now we have rules and regulations and other nonsense! They've given us some neutered version of the perfected blight and expect us to weaponize it. If I'm to get this crap functional I'll need several bags full of ferocious doomweed . You'll find it all over Silverpine.",starts={{npcID=44778,x=0.566,y=0.092,mapID=21}},ends={{npcID=44778,x=0.566,y=0.092,mapID=21}},coords={x=0.566,y=0.092,source="quest_giver",mapID=21},questType="standard"},
[27547] = {id=27547,name="Of No Consequence",level=5,requiredLevel=5,faction="horde",expansion=9,zoneID=130,mapID=21,description="Our forces in Pyrewood were recently taken by way of sneak attack. The 7th Legion managed to infiltrate the town with their scouts, ultimately decimating our troops. The Dark Lady has tasked us with a rescue mission. We are to find survivors and get them out of Pyrewood safely. If any soldiers live they are likely worthless, but we do as the Dark Lady commands. Let's get this nonsense over with, . Pyrewood is directly southwest of the Forsaken Front.",starts={{npcID=45880,x=0.445,y=0.732,mapID=21}},ends={{npcID=45880,x=0.445,y=0.732,mapID=21}},coords={x=0.445,y=0.732,source="quest_giver",mapID=21},questType="standard"},
