[65008] = {id=65008,name="Goat Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Goat Soul is stoic and unwavering. The shape of the goat will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65009] = {id=65009,name="Ram Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Ram Soul is brave and fierce. The shape of the ram will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65010] = {id=65010,name="Alpaca Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Alpaca Soul is wary and alert. The shape of the alpaca will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
