[65022] = {id=65022,name="Sporebat Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Sporebat Soul is quick and alert. The shape of the sporebat will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65023] = {id=65023,name="Jormungar Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Jormungar Soul is fierce and determined. The shape of the jormungar will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65024] = {id=65024,name="Cloud Serpent Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Cloud Serpent Soul is energetic and loyal. The shape of the cloud serpent will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65025] = {id=65025,name="Boar Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Boar Soul is fierce and cunning. The shape of the boar will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65026] = {id=65026,name="Owl Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Owl Soul is solemn and smart. The shape of the owl will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65036] = {id=65036,name="Train Like We Fight",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="Jumping through hoops is helpful to get your bearings, but we train like we fight--relentlessly. Go ahead and try Soaring around the area until you feel you have mastered the technique. Of course you must be mindful of the local wildlife and keep an eye out for any potential threats. That is why we practice, after all. Report back to Emberthal when you feel you are ready. Good luck!",starts={{npcID=192889,x=0.448,y=0.578,mapID=85}},ends={{npcID=181054,x=0.444,y=0.61,mapID=85}},coords={x=0.448,y=0.578,source="quest_giver",mapID=85},questType="standard"},
[65045] = {id=65045,name="Stormsunder Crater",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="Dervishian's report is troubling. An enemy force calling themselves the Primalists have invaded Stormsunder Crater, pinning the Ebon Scales down at the Siege Creche. These intruders are summoning violent elementals and recruiting the vicious tarasek to their cause. Azurathel will need your help at the crater. By wing or by talon, save our people. Once the Ebon Scales are safe, ask their commander to rendezvous with me. Be warned. Sarkareth can be... prickly.",starts={{npcID=181054,x=0.444,y=0.61,mapID=85}},ends={{npcID=182274,x=0.702,y=0.644,mapID=85}},coords={x=0.444,y=0.61,source="quest_giver",mapID=85},questType="standard"},
[65046] = {id=65046,name="The Primalists",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="My memories are still clouded from stasis, but I am certain we have encountered these Primalists before. Dervishian grits her fangs.> It is no use. Trying to remember feels like chasing fragments of a dream. Perhaps you can fare better. Look for any clues as to what--or who--motivates these invaders.",starts={{npcID=186210,x=0.702,y=0.644,mapID=85}},ends={{npcID=186218,x=0.794,y=0.622,mapID=85}},coords={x=0.702,y=0.644,source="quest_giver",mapID=85},questType="standard"},
[65049] = {id=65049,name="Tangle with the Tarasek",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The tarasek are unpredictable and wild. Like primordial drakonid, if you will. Neltharion considered them little more than fodder. Targets for our training. But they are cunning hunters, and deadly when encountered in packs. Should they gain elemental power from these Primalists, they will become even more dangerous. We cannot let that happen, . Thin their numbers.",starts={{npcID=182274,x=0.702,y=0.644,mapID=85}},ends={{npcID=182275,x=0.794,y=0.622,mapID=85}},coords={x=0.702,y=0.644,source="quest_giver",mapID=2151},questType="standard"},
[65050] = {id=65050,name="Conjured Army",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="These Primalists are summoning an army of elementals. We have to assume they mean to unleash them against our forces. Well, not on our watch. Rain fire upon them, evoker! Burn those elementals from the Reach, and take out their conjurers before they summon more.",starts={{npcID=182274,x=0.702,y=0.644,mapID=85}},ends={{npcID=182275,x=0.794,y=0.622,mapID=85}},coords={x=0.702,y=0.644,source="quest_giver",mapID=2151},questType="standard"},
[65052] = {id=65052,name="The Ebon Scales",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="We got past the Primalist incursion. Now we must reach the creche. Scalecommander Sarkareth is as tough as they come, and his weyrn holds the line. But a dragon has the Ebon Scales pinned down. Time for us to join the fight! Take point. Give the signal when we are in range of the dragon. Then we hit it with everything we have. Watch out for ambushes. I have a bad feeling about this.",starts={{npcID=182275,x=0.794,y=0.622,mapID=85}},ends={{npcID=182297,x=0.81,y=0.54,mapID=85}},coords={x=0.794,y=0.622,source="quest_giver",mapID=85},questType="standard"},
[65057] = {id=65057,name="Rally to Emberthal",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="Now that the fight is done, you ask me to report in to Emberthal. Does Azurathel expect me to follow her commands? I think not. The Ebon Scales answer only to the Earth-Warder. And thus far, I have received no orders from Neltharion. Still, I am not blind to the threat these Primalists represent. I am certain I have fought their kind before, and yet... We will rally to the grounds once my people have recovered. You are dismissed, evoker.",starts={{npcID=182297,x=0.81,y=0.54,mapID=85}},ends={{npcID=181054,x=0.444,y=0.61,mapID=85}},coords={x=0.81,y=0.54,source="quest_giver",mapID=85},questType="standard"},
[65060] = {id=65060,name="Caldera of the Menders",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="Your vision from the arcane beacon showed that there are dracthyr trapped within their creches. We cannot afford to lose any more of our people. The Healing Wings are the finest medics in our ranks. Their creche lies within the Caldera of the Menders. Cindrethresh knows the way. Leave no one behind, evoker.",starts={{npcID=181054,x=0.444,y=0.61,mapID=85}},ends={{npcID=184214,x=0.202,y=0.19,mapID=85}},coords={x=0.444,y=0.61,source="quest_giver",mapID=85},questType="standard"},
[65063] = {id=65063,name="Into the Hive",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="Whatever toxin has infested this creche is potent enough to take down our best healers. That does not bode well for either one of us, . No matter. Dracthyr are trapped inside. We are going in, regardless of risk. Take a deep breath and follow me!",starts={{npcID=184214,x=0.202,y=0.19,mapID=85}},ends={{npcID=184163,x=0.202,y=0.19,mapID=85}},coords={x=0.202,y=0.19,source="quest_giver",mapID=85},questType="standard"},
[65065] = {id=65065,name="The Tuskarr",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="Oh, excuse me but we did not know your kind was on this island. We are only newly arrived to these shores looking for a unclaimed land to call a home. We mean no harm and will move on if this land truly is forbidden. My son To'no is quite the fan of dragonkin of all sorts and I am sure would have many questions for you. He is my little explorer. If you see him before I do know that you may be accosted by many questions. Now where did that little moo get to...?",starts={{npcID=184164,x=0.156,y=0.598,mapID=85}},ends={{npcID=184166,x=0.334,y=0.332,mapID=85}},coords={x=0.156,y=0.598,source="quest_giver",mapID=85},questType="standard"},
[65071] = {id=65071,name="Halp!",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="I need halp! I am To'no and I was exploring cuz that is what I am good at but I did not realize my sister Ko followed me and I need you to halp me find her cuz she is in trouble so please halp please? She went into this cave but she is not as good at hiding as I am and our parents are too far away to halp. Can you find her before the monsters do?",starts={{npcID=184166,x=0.334,y=0.332,mapID=85}},ends={{npcID=184212,x=0.218,y=0.294,mapID=85}},coords={x=0.334,y=0.332,source="quest_giver",mapID=85},questType="standard"},
[65073] = {id=65073,name="A Toxic Problem",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="You recover quickly, . Good. Those who escaped my creche are healing, but others remain trapped inside. Rush in to save them and I will just have to drag you out again. There are beetle nests scattered around the caldera. Their toxin glands might provide a way to counter the effects of that poison. I am in no shape to collect them myself. I must rely upon your skills, evoker.",starts={{npcID=184163,x=0.202,y=0.19,mapID=85}},ends={{npcID=184163,x=0.202,y=0.19,mapID=85}},coords={x=0.202,y=0.19,source="quest_giver",mapID=2151},questType="standard"},
[65074] = {id=65074,name="Easy Prey",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The wilds surrounding this creche are home to scythid. They are voracious insectoids, often territorial and aggressive. All these wounded would be easy prey for those beasts. I do not want them attacking our Menders while they recover. Cull their numbers while I look after Viridia. She is.. very brave.",starts={{npcID=184214,x=0.202,y=0.19,mapID=85}},ends={{npcID=184214,x=0.202,y=0.19,mapID=85}},coords={x=0.202,y=0.19,source="quest_giver",mapID=2151},questType="standard"},
[65075] = {id=65075,name="The Healing Wings",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="Evoker, you have my gratitude for aiding my weyrn in our most desperate hour. After we regain our strength, the Healing Wings will rendezvous with the rest of our forces. Cindre tells me that Emberthal lost everyone from her weyrn. I fear I have no magic that can heal such a wound. She may seem stoic, but Emberthal feels this loss deeply, . Tell her I am on my way.",starts={{npcID=184163,x=0.202,y=0.19,mapID=85}},ends={{npcID=181054,x=0.444,y=0.61,mapID=85}},coords={x=0.202,y=0.19,source="quest_giver",mapID=85},questType="standard"},
[65084] = {id=65084,name="The Froststone Vault",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="Look there, across the Reach! Primalist forces are converging on Froststone Vault. The storm they seek to unleash must be locked inside. We fought this enemy before, and won. Neltharion commanded that the vault be secured, but I... cannot remember why... This is no time for contemplation. Rally with Sarkareth and the Ebon Scales at the vault. Ensure the enemy does not breach it!",starts={{npcID=182258,x=0.448,y=0.578,mapID=85}},ends={{npcID=184308,x=0.562,y=0.288,mapID=85}},coords={x=0.448,y=0.578,source="quest_giver",mapID=85},questType="standard"},
[65087] = {id=65087,name="The Prize Inside",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="So the Primalists want what's inside this vault? Let them come. We will show them what the dracthyr were born to do!",starts={{npcID=184308,x=0.562,y=0.288,mapID=85}},ends={{npcID=184308,x=0.562,y=0.288,mapID=85}},coords={x=0.562,y=0.288,source="quest_giver",mapID=85},questType="standard"},
[65097] = {id=65097,name="Run!",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Storms are about to overwhelm us! We must evacuate! Save everyone you can. And find those black dragons!",starts={{npcID=182441,x=0.54,y=0.322,mapID=85}},ends={{npcID=182601,x=0.472,y=0.354,mapID=85}},coords={x=0.54,y=0.322,source="quest_giver",mapID=2151},questType="standard"},
[65098] = {id=65098,name="The Consequence of Courage",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="Thank you for healing me, . I hope that we are earning one another's trust. Wrathion shudders.> The Storm-Eater. I have never faced a dragon of such raw elemental power. If there are others like her... Wait... where is Ebyssian ? Did he survive? You must find him!",starts={{npcID=182601,x=0.472,y=0.354,mapID=85}},ends={{npcID=191780,x=0.416,y=0.444,mapID=85}},coords={x=0.472,y=0.354,source="quest_giver",mapID=85},questType="standard"},
[65100] = {id=65100,name="Final Orders",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="The storm unleashed by Raszageth is too powerful. We must evacuate the only home we have ever known. There is no longer an Earth-Warder to command us. For the first time, we are free to make our own choices. To find our own fate. Wherever you go in this new age, I hope you find worthy allies. Tell them our story. As for me, I will stay here and look for survivors. Along the way, I may find answers about our past. May fortune favor us all, $p.",starts={{npcID=191780,x=0.416,y=0.444,mapID=85}},ends={{npcID=182609,x=0.468,y=0.558,mapID=85},{npcID=182612,x=0.446,y=0.552,mapID=85}},coords={x=0.416,y=0.444,source="quest_giver",mapID=85},questType="standard"},
[65101] = {id=65101,name="An Iconic, Draconic Look",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,mapID=84,description="You turned every head in Stormwind with your arrival, $p. No doubt some citizens were more... amenable to your presence than others. In order to better commune with other races, we dragons adopt a mortal visage , like the one you see before you. Not only does it put allies at ease, but it makes passing through doorways considerably less disruptive. Clearly the essence of dragonkind flows through the dracthyr. I suspect you may share our ability to assume a visage . Walk with me.",starts={{npcID=189569,x=0.798,y=0.272,mapID=84}},ends={{npcID=194022,x=0.826,y=0.238,mapID=84}},coords={x=0.798,y=0.272,source="quest_giver",mapID=84},questType="standard"},
