[65307] = {id=65307,name="Mercy First",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="The toxicity in the creche nearly claimed us all. While the antidote is being prepared, I need you to seek out the wounded and heal them. Yes, even the blue drakonid. The Healing Wings do not stand idly by while others suffer.",starts={{npcID=184163,x=0.202,y=0.19,mapID=85}},ends={{npcID=184163,x=0.202,y=0.19,mapID=85}},coords={x=0.202,y=0.19,source="quest_giver",mapID=85},questType="standard"},
