[65437] = {id=65437,name="Aspectral Invitation",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=1637,mapID=85,description="Your arrival is well timed, $p. I have just met with the Horde Council, and they have accepted the Aspects' invitation to the Dragon Isles . The same invitation extends to you, as well. You may also notice some unfamiliar faces here in Orgrimmar. The dracthyr are new arrivals you will learn about on the journey ahead. Let us speak more.",starts={{npcID=190239,x=0.558,y=0.126,mapID=1},{npcID=190239,x=0.442,y=0.382,mapID=85}},ends={{npcID=190239,x=0.558,y=0.126,mapID=1},{npcID=190239,x=0.442,y=0.382,mapID=85}},coords={x=0.558,y=0.126,source="quest_giver",mapID=85},questType="standard"},
[65443] = {id=65443,name="Expeditionary Coordination",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=14,mapID=1,description="Pleasure to meet you, I am Naleidea Rivergleam . The invitation to visit the Dragon Isles is quite an exciting prospect. Don't you agree? The Reliquary has combined forces with our expeditionary counterparts to help coordinate our efforts. As a member of the Dragonscale Expedition, it is my honor to welcome you. Though first we must gather a few more members for our journey. Shall we begin?",starts={{npcID=184793,x=0.442,y=0.38,mapID=85}},ends={{npcID=197279,x=0.558,y=0.126,mapID=1}},coords={x=0.442,y=0.38,source="quest_giver",mapID=1},questType="standard"},
[65467] = {id=65467,name="Turkey Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Turkey Soul is bold and fierce. The shape of the turkey will be yours to call upon.>",questType="standard"},
