[65513] = {id=65513,name="Gromit Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Gromit Soul is exuberant and inquisitive. The shape of the gromit will be yours to call upon.>",questType="standard"},
