[65515] = {id=65515,name="Pig Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Pig Soul is curious and tenacious. The shape of the pig will be yours to call upon.>",questType="standard"},
[65516] = {id=65516,name="Sheep Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Sheep Soul is calm and stalwart. The shape of the sheep will be yours to call upon.>",questType="standard"},
[65517] = {id=65517,name="Penguin Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Penguin Soul is playful and sociable. The shape of the penguin will be yours to call upon.>",questType="standard"},
[65518] = {id=65518,name="Bee Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Bee Soul is protective and spry. The shape of the bee will be yours to call upon.>",questType="standard"},
[65519] = {id=65519,name="Snail Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Snail Soul is cautious and patient. The shape of the snail will be yours to call upon.>",questType="standard"},
[65613] = {id=65613,name="An Iconic, Draconic Look",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=1637,mapID=85,description="I am sure your arrival in Orgrimmar drew the attention of its citizens. No doubt some were more comfortable in your presence than others. When I was a young dragon, I took on the mortal visage you now see. It allowed me to live among the tauren of Highmountain as an ally. Though your path differs from mine, the essence of dragonkind flows through you as well, $p. Perhaps that will allow you to assume a visage of your own. Let us walk together.",starts={{npcID=190239,x=0.558,y=0.126,mapID=1},{npcID=190239,x=0.442,y=0.382,mapID=85}},ends={{npcID=190239,x=0.558,y=0.126,mapID=1},{npcID=190239,x=0.442,y=0.382,mapID=85}},coords={x=0.558,y=0.126,source="quest_giver",mapID=85},questType="standard"},
[65615] = {id=65615,name="Arcane Intrusion",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="That beacon ahead--I am certain it was not there before we were imprisoned. Spellcraft is not my forte, but I know arcane magic when I see it. The same magic used by the blue dragon in the creche. He said a name... Malygos. It sounds so familiar, but the Earth-Warder's teachings feel distant. Fragmented. If this Malygos put us into stasis, perhaps the arcane beacon was placed on his orders. Investigate the area and report back. Ensure the beacon cannot be used to call in enemy reinforcements.",starts={{npcID=182251,x=0.442,y=0.614,mapID=85}},ends={{npcID=182251,x=0.442,y=0.614,mapID=85}},coords={x=0.442,y=0.614,source="quest_giver",mapID=85},questType="standard"},
[65640] = {id=65640,name="Cervid Soul",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=12858,mapID=1565,description="Cervid Soul is noble and wise. The shape of the cervid will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[65656] = {id=65656,name="Call to Lordaeron",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=13983,mapID=2070,description="With the Shadowlands healing, it is time to turn our attention to matters close to home again, on Azeroth. The Forsaken are mustering in the ruins of the kingdom of Lordaeron. They seek to reclaim as much as they can of the Tirisfal Glades, to finally put the destruction left by the Fourth War behind them. And I intend to assist them in any way I can. I also know that for the Horde, I have much to prove. Come, join me in Brill and we can help the Forsaken together.",starts={{npcID=173386,x=0.506,y=0.758,mapID=85}},ends={{npcID=185512,x=0.608,y=0.514,mapID=2070}},coords={x=0.506,y=0.758,source="quest_giver",mapID=2070},questType="standard"},
[65701] = {id=65701,name="Preservation, Augmentation, or Devastation",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="If what these dragons say is true, then a great battle is upon us. We need you focused and strong, evoker. Time to choose your battle specialization. Will you preserve your allies, or devastate your enemies? To hone your combat skills to their sharpest, choose Devastation. To maximize your healing potential, take the path of Preservation. To enhance your wingmates, embrace Augmentation. Each specialization should serve you well. And remember, you can change or adapt it later.",starts={{npcID=182258,x=0.448,y=0.578,mapID=85}},ends={{npcID=182258,x=0.448,y=0.578,mapID=85}},coords={x=0.448,y=0.578,source="quest_giver",mapID=85},questType="standard"},
[65703] = {id=65703,name="Shadowlands (60) E",level=60,requiredLevel=60,faction="none",expansion=9,questType="standard"},
[65704] = {id=65704,name="Shadowlands (60) E",level=60,requiredLevel=60,faction="none",expansion=9,questType="standard"},
[65705] = {id=65705,name="Shadowlands (60) E",level=60,requiredLevel=60,faction="none",expansion=9,questType="standard"},
[65771] = {id=65771,name="Favor of the First Ones",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13536,mapID=1970,description="The attack from the Jailer's forces is a sign! In the past, there was one among us who sought the forbidden knowledge of the First Ones. For that, we must have earned their ire and lost the protections we once had. We must atone for the trespasses of our kin. Take this incense. Go out into the veldt and burn it as offerings to the First Ones. I hope they will offer us forgiveness.",starts={{npcID=178015,x=0.348,y=0.648,mapID=1970}},ends={{npcID=178015,x=0.348,y=0.648,mapID=1970}},coords={x=0.348,y=0.648,source="quest_giver",mapID=1970},questType="standard"},
[65777] = {id=65777,name="Mudcaked Necklace",level=50,requiredLevel=50,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[65801] = {id=65801,name="Making Introductions",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Sansok Khan signs, Okir vocalizes for her.> It has been countless generations since an outsider like you reached our lands. With Primalists treading on our lands and peddling forbidden magics, my people are understandably wary. If you are to travel with us, you must make yourself known. Introduce yourself to the members of my clan.",starts={{npcID=181217,x=0.856,y=0.252,mapID=2023}},ends={{npcID=185882,x=0.756,y=0.316,mapID=2023}},coords={x=0.856,y=0.252,source="quest_giver",mapID=2023},questType="standard"},
[65865] = {id=65865,name="They've Got Us Pinned Down!",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[65874] = {id=65874,name="A Rotten Revelation",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="Hmm... We've got to put our whiskers together and determine what this means.",questType="standard"},
[66004] = {id=66004,name="Galgresh",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[66033] = {id=66033,name="To the... Past?",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=14092,mapID=2092,description="It is regrettable that we could not stabilize Chronormu, but there is another potential location where we may be able to catch her and bring an end to her fall through time. Nozdormu frowns.> The glimpses of this timeline past are... strange. Even among some of the visions I have witnessed in my life. Be on your guard, . I am uncertain what you will face, but it is powerful and... oddly familiar.",starts={{npcID=186931,x=0.6,y=0.824,mapID=2025}},ends={{npcID=187344,x=0.598,y=0.662,mapID=2092}},coords={x=0.6,y=0.824,source="quest_giver",mapID=2092},questType="standard"},
[66074] = {id=66074,name="Primal Scythid Queen",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66091] = {id=66091,name="Path of the Dark Rangers",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=13983,mapID=2070,starts={{npcID=185851,x=0.618,y=0.678,mapID=2070}},ends={{npcID=185851,x=0.618,y=0.678,mapID=2070}},coords={x=0.618,y=0.678,source="quest_giver",mapID=2070},questType="standard"},
[66176] = {id=66176,name="Elemental Experimentation",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="Go conduct experiments on the water elementals harassing the gorlocs!",questType="standard"},
[66190] = {id=66190,name="So Close",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13645,mapID=2023,description="I must take a moment to thank you, , for all your help. Truly, I never thought I would have a chance to admire the Dream within Ancient Bough! Not as a humble emissary! How very kind. Lord Somnikus has graciously invited me to set foot inside the grove and see the portal. I would be honored if you would join me. I will remember this moment for the rest of my life. Share it with me.",starts={{npcID=189857,x=0.22,y=0.508,mapID=2023}},ends={{npcID=187561,x=0.22,y=0.492,mapID=2023}},coords={x=0.22,y=0.508,source="quest_giver",mapID=2023},questType="standard"},
[66212] = {id=66212,name="Fishing: Aileron Seamoth",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Doesn't ANYBODY know how to fish PROPERLY anymore? Lukoturukk wiggles his nose angrily.> You, with the face, go get me some fish. GOOD fish. And no grungles!",starts={{npcID=193877,x=0.14,y=0.494,mapID=2024}},ends={{npcID=193877,x=0.14,y=0.494,mapID=2024}},coords={x=0.14,y=0.494,source="quest_giver",mapID=2112},questType="standard"},
[66223] = {id=66223,name="Can We Keep It?",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=14433,mapID=2151,description="He's only trying to eat us because he's so hungry! Fish! Nobody can turn down some tasty, ice cold, raw fish! Frigidfish are the best, ever. You can fish them up all over the ocean! But if you can't fish one yourself, Jinkutuk in Iskaara will definitely sell you some. Bring me so many he won't be hungry any more!",starts={{npcID=187674,x=0.106,y=0.468,mapID=2024}},ends={{npcID=187674,x=0.106,y=0.468,mapID=2024}},coords={x=0.106,y=0.468,source="quest_giver",mapID=2151},questType="standard"},
[66237] = {id=66237,name="Spiritual Allies",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=14,mapID=1,description="Our arrival will not have gone unnoticed. Allow me to speak with them before we enter. I have something of a history with the council. There will be time for introductions after.",starts={{npcID=189386,x=0.456,y=0.128,mapID=1}},ends={{npcID=189389,x=0.456,y=0.128,mapID=1}},coords={x=0.456,y=0.128,source="quest_giver",mapID=1},questType="standard"},
[66241] = {id=66241,name="Thaldraszus Rally",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13647,mapID=2025,questType="standard"},
[66244] = {id=66244,name="To Valdrakken",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Thanks to you, we narrowly avoided a complete catastrophe. However, we should convene with the other Aspects and share word of what happened here. Please meet me at the Seat of the Aspects within Valdrakken. I'm sure the others will have insight into what Raszageth and her Primalists are attempting. There is a crossing into Thaldraszus north and a bit east of here. The flight is scenic, but do not take too long getting there.",starts={{npcID=190000,x=0.394,y=0.63,mapID=2024}},ends={{npcID=187658,x=0.574,y=0.586,mapID=2025},{npcID=187678,x=0.58,y=0.358,mapID=2112}},coords={x=0.394,y=0.63,source="quest_giver",mapID=2112},questType="standard"},
[66324] = {id=66324,name="Never Forgotten",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13769,mapID=85,description="The antidote is ready. Use it to search the Support Creche for survivors. Work quickly--the effect will not last long, so you may have to reapply it. If any of my people yet draw breath, save them. And if they do not, I ask that you recover their horn signets so that their names may be honored. While inside, perhaps you can find evidence of how this infestation came to be.",starts={{npcID=184163,x=0.202,y=0.19,mapID=85}},ends={{npcID=184163,x=0.202,y=0.19,mapID=85}},coords={x=0.202,y=0.19,source="quest_giver",mapID=85},questType="standard"},
[66349] = {id=66349,name="Training Rock",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=10424,mapID=1409,description="Remove those rocks!",questType="standard"},
[66418] = {id=66418,name="Testing the Tuskarrsenal",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13644,mapID=2022,description="The first weapon is ready! Soaking the bones in river water warmed by the djaradin's fire made them more pliable. I'll remember that trick! Since you've been helpful so far, I'll do you the honor of letting you test out some authentic Uktulut weaponry. You'll find no sharper blade or sturdier haft this side of the Dragon Isles. Go test this out in our training area for me. Maybe it'll remind the chieftain what real fighting looks like! Ha!",starts={{npcID=188285,x=0.542,y=0.386,mapID=2022}},ends={{npcID=188285,x=0.542,y=0.386,mapID=2022}},coords={x=0.542,y=0.386,source="quest_giver",mapID=2022},questType="standard"},
[66484] = {id=66484,name="Know Your Enemy: Proto-Dragons",level=10,requiredLevel=10,faction="none",expansion=9,questType="standard"},
[66504] = {id=66504,name="A Shard of Crystalized Mana",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="Lathos may find it interesting.",questType="standard"},
[66507] = {id=66507,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[66508] = {id=66508,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=1637,mapID=85,starts={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},ends={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[66509] = {id=66509,name="Paranoid 1",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,description="Agura sent me out here to pick FLOWERS for my ANXIETY but there are CREATURES and I'm terrified.",questType="standard"},
[66513] = {id=66513,name="Ground Leave",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,mapID=84,description="Perhaps we should get an idea of this city, if it is to be our new home. A scouting mission, if you will. Go, see what this place has to offer. I will follow Wrathion and attempt to help in any way I can. Try not to upset the locals any more than you must, though. I doubt many of them are used to seeing dragons walk among them. Meet up with us once you've gotten the lay of the land.",starts={{npcID=189324,x=0.322,y=0.496,mapID=37}},ends={{npcID=189603,x=0.798,y=0.272,mapID=84}},coords={x=0.322,y=0.496,source="quest_giver",mapID=84},questType="standard"},
[66534] = {id=66534,name="Ground Leave",level=10,requiredLevel=10,faction="horde",expansion=9,zoneID=1637,mapID=85,description="It seems like our arrival was noticed after all. Maybe there's hope for these people yet. I'll follow up with Ebyssian and the Horde leadership and try to smooth this out. You're on recon. See what this place has to offer. We may be here for a while, after all. Come find us once you're finished. Hopefully we'll have all the boring bits sorted out by then.",starts={{npcID=189389,x=0.456,y=0.128,mapID=1}},ends={{npcID=184786,x=0.442,y=0.382,mapID=85}},coords={x=0.456,y=0.128,source="quest_giver",mapID=85},questType="standard"},
[66549] = {id=66549,name="Waking Shores Rally",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66575] = {id=66575,name="Item as Questgiver: Vial",level=40,requiredLevel=40,faction="none",expansion=9,zoneID=13823,questType="standard"},
[66577] = {id=66577,name="Aspectral Invitation",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,mapID=84,description="Ah, $p. Impeccable timing! I just met with Lord Commander Turalyon and his allies, and they have accepted the Aspects' invitation to the Dragon Isles . You will be coming along, of course? It wouldn't be the same without you! I imagine you have noticed some unfamiliar faces gathered here. The ones with the wings are called dracthyr. They have only known me a short time, but they are already great admirers. Ah, but where are my manners? We should have a chat.",starts={{npcID=189569,x=0.798,y=0.272,mapID=84}},ends={{npcID=189569,x=0.798,y=0.272,mapID=84}},coords={x=0.798,y=0.272,source="quest_giver",mapID=84},questType="standard"},
[66589] = {id=66589,name="Expeditionary Coordination",level=10,requiredLevel=10,faction="alliance",expansion=9,zoneID=1519,mapID=84,description="The name's Toddy. I'll be headin' up our band of cheery adventurers under the banner of the Dragonscale Expedition. We'll get into the details later. For now, let's focus on gatherin' up our crew. Every expedition worth its salt has a variety of folk. We'll be needin' scholars, artisans, and of course explorers. Well? What're you standin' here for? Assemble that crew!",starts={{npcID=189602,x=0.798,y=0.272,mapID=84}},ends={{npcID=189077,x=0.228,y=0.556,mapID=84}},coords={x=0.798,y=0.272,source="quest_giver",mapID=84},questType="standard"},
[66611] = {id=66611,name="Clearing the Skies",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,description="Can you hear that? Bugs! All around. Some of them are getting pretty big. Why don't you and your gliding friend use the thermal behind me and do something about it?",questType="standard"},
[66649] = {id=66649,name="Turning the Wheel",level=60,requiredLevel=60,faction="none",expansion=9,questType="raid"},
[66650] = {id=66650,name="Fate's Finale",level=60,requiredLevel=60,faction="none",expansion=9,questType="raid"},
[66654] = {id=66654,name="Desecrator Annihilator",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,mapID=2023,description="My mother was a hero. She deserves peace and rest, not this... enslavement! None of our heroes do. They must pay for this. And our ancestors must rest once more with their weapons, with honor. Take the weapons back from those desecrators!",starts={{npcID=188225,x=0.39,y=0.66,mapID=2023}},ends={{npcID=189858,x=0.338,y=0.654,mapID=2023}},coords={x=0.39,y=0.66,source="quest_giver",mapID=2023},questType="standard"},
[66661] = {id=66661,name="It's Just a Coin, What Could it Cost?",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=10565,mapID=1670,questType="standard"},
[66676] = {id=66676,name="Sneaking In",level=20,requiredLevel=20,faction="both",expansion=9,zoneID=13645,mapID=2023,description="This is Lizi... she's my secret friend. I've been taking care of her since she was rejected by her mother. This isn't looking good. Whatever they did to her is beyond my knowledge. I have to bring her home. My Ohn may ground me for the rest of time, but Lizi must get help. I am ever grateful to you, $p. I'm sorry this was more trouble than you signed up for. If you wouldn't mind one more adventure... please face my Ohn's wrath with me? Meet me back at the springs.",starts={{npcID=190014,x=0.562,y=0.77,mapID=2023}},ends={{npcID=190014,x=0.562,y=0.77,mapID=2023}},coords={x=0.562,y=0.77,source="quest_giver",mapID=2023},questType="standard"},
[66691] = {id=66691,name="Waking Shores - Race 01 - Intermediate",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66722] = {id=66722,name="Wild Preserve Slalom - Advanced",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66725] = {id=66725,name="Wild Preserve Circuit",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66729] = {id=66729,name="Conditionals",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="I don't like the alliance. Remember me? Go kill Mawsworn.",questType="standard"},
[66733] = {id=66733,name="Apex Canopy River Run - Advanced",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66880] = {id=66880,name="Ravine River Run",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[66885] = {id=66885,name="Emerald Gardens Ascent",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[66935] = {id=66935,name="Crystal Quill Pens",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="There are unique creatures in these lands called crystalspines. They are cute little creatures protected by sharp crystal quills . When I was treating one of our researchers for being stuck by one, I noticed that there was a lingering power resonating within. They might make for an excellent source of enchanting crystals.",starts={{npcID=191001,x=0.368,y=0.626,mapID=2112}},ends={{npcID=191001,x=0.368,y=0.626,mapID=2112}},coords={x=0.368,y=0.626,source="quest_giver",mapID=2112},questType="standard"},
[66956] = {id=66956,name="Dragonhunter Igordan",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66960] = {id=66960,name="Klozicc the Ascended",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[66970] = {id=66970,name="Ty'foon the Ascended",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
