[70034] = {id=70034,name="Artisan's Supply: Salamanther Scales",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Are you looking for work, skinner? The Artisan's Consortium asked me to gather the scales of a salamanther for their customers. I may be an artisan, but I am no one's errand child! But... ah, perhaps you could find some?",starts={{npcID=191392,x=0.81,y=0.594,mapID=2023},{npcID=194185,x=0.846,y=0.232,mapID=2023},{npcID=192558,x=0.766,y=0.348,mapID=2022}},ends={{npcID=192498,x=0.578,y=0.682,mapID=2022}},coords={x=0.81,y=0.594,source="quest_giver",mapID=2151},questType="standard"},
