[70235] = {id=70235,name="Repair Bill",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The Dragon Isles have not experienced conflict like this in millennia. Our work is not in dispute, but any good armor suffers from all of this constant use. I have a big order for Serevite Repair Hammers and I need everyone I can get to fill it. If you help out, I will again give you more information to expand your Dragon Isles Blacksmithing skills.",starts={{npcID=185546,x=0.37,y=0.468,mapID=2112}},ends={{npcID=185546,x=0.37,y=0.468,mapID=2112}},coords={x=0.37,y=0.468,source="quest_giver",mapID=2151},questType="standard"},
