[70613] = {id=70613,name="Get Their Bark Before They Bite",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13844,mapID=2025,description="$p, you are a skilled herbalist, are you not? I have alchemists nearly begging at my door... well, if I had a door... for more Writhebark . We have nearly sold out! Will you help me gather more? I fear if the alchemists cannot create the phials they need, they will begin experimenting with my belongings.",starts={{npcID=185549,x=0.38,y=0.684,mapID=2112}},ends={{npcID=185549,x=0.38,y=0.684,mapID=2112}},coords={x=0.38,y=0.684,source="quest_giver",mapID=2025},questType="standard"},
[70614] = {id=70614,name="Bubble Craze",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13844,mapID=2025,description="Agrikus shouts at you.> I have no more poppy tea! ...Oh, you're not one of them. Praise the Titans. Someone made \" Bubble Poppy Tea\" the most fashionable drink on the market this week and I've sold out of the herb completely. Please, could you bring more poppies before they return in droves?",starts={{npcID=185549,x=0.38,y=0.684,mapID=2112}},ends={{npcID=185549,x=0.38,y=0.684,mapID=2112}},coords={x=0.38,y=0.684,source="quest_giver",mapID=2025},questType="standard"},
[70615] = {id=70615,name="The Case of the Missing Herbs",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13844,mapID=2025,description="Aah, $p! There you are! They took it! They took my Saxifrage ! I left for barely two hours, and when I returned, someone had taken my Saxifrage ! All they left to show for their crimes was this heavy sack of gold coins. As if you could put a price on herbs! ...Please $p, I need more Saxifrage to replenish what that criminal took from me.",starts={{npcID=185549,x=0.38,y=0.684,mapID=2112}},ends={{npcID=185549,x=0.38,y=0.684,mapID=2112}},coords={x=0.38,y=0.684,source="quest_giver",mapID=2025},questType="standard"},
[70616] = {id=70616,name="How Many??",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13844,mapID=2025,description="Agrikus is crying as you approach.> They did it... I cannot believe they did it... Someone has come here and asked for the delivery of ONE THOUSAND herbs! I cannot even fathom this! It is preposterous. Ridiculous! Ludicrous!! ...Please help.",starts={{npcID=185549,x=0.38,y=0.684,mapID=2112}},ends={{npcID=185549,x=0.38,y=0.684,mapID=2112}},coords={x=0.38,y=0.684,source="quest_giver",mapID=2025},questType="standard"},
[70617] = {id=70617,name="All Mine, Mine, Mine",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14030,mapID=2112,description="There is nothing as useful as Draconium ore . So much can be done with it! It is the perfect ore, pure in every way. Bring me Draconium. I must have it. You are a miner, yes? Then go mine!",starts={{npcID=185553,x=0.39,y=0.512,mapID=2112}},ends={{npcID=185553,x=0.39,y=0.512,mapID=2112}},coords={x=0.39,y=0.512,source="quest_giver",mapID=2112},questType="standard"},
[70618] = {id=70618,name="The Call of the Forge",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14529,mapID=2200,description="The forge... she calls to me. And she asks for Serevite. You there! Bring me Serevite! Yes, lots of Serevite!",starts={{npcID=185553,x=0.39,y=0.512,mapID=2112}},ends={{npcID=185553,x=0.39,y=0.512,mapID=2112}},coords={x=0.39,y=0.512,source="quest_giver",mapID=2200},questType="standard"},
[70640] = {id=70640,name="WANTED: Boss",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="Previously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. While this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land. Please see that it is safely neutralized. Bring word of your success to Custodian Cynegos.",questType="standard"},
[70641] = {id=70641,name="A Waking Oath",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,description="Hold a moment, $p. I wish to personally thank you for your aid in restoring our oathstone. I was not aware of the dracthyr until your reawakening on the Forbidden Reach. It was unclear what your arrival among us meant. Whether your kind would prove to be a boon to the defense of life... or a bane. I would encourage you to learn more about our oathstone. Speak with a few of my flight here at the Ruby Lifeshrine. Perhaps you will find familiarity among our tales.",starts={{npcID=185905,x=0.622,y=0.73,mapID=2022}},ends={{npcID=185905,x=0.622,y=0.73,mapID=2022}},coords={x=0.622,y=0.73,source="quest_giver",mapID=2022},questType="standard"},
[70648] = {id=70648,name="Firava the Rekindler",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[70698] = {id=70698,name="Researcher Sneakwing",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[70706] = {id=70706,name="Waygate: Shady Sanctuary",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,description="Our expedition reports a dormant stone out in the lush hillsides to the southwest. It's quite a journey, but worth sendin' someone with yer knowledge tae investigate.",questType="standard"},
