[70748] = {id=70748,name="For Blue Eyes Only",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="It is no wonder your companions have yet to find anything. These books were meant for blue eyes only. However, my presence should suffice in allowing for some of the more pertinent tomes to divulge their secrets.",starts={{npcID=197378,x=0.424,y=0.638,mapID=2024}},ends={{npcID=197378,x=0.424,y=0.638,mapID=2024}},coords={x=0.424,y=0.638,source="quest_giver",mapID=2024},questType="standard"},
[70751] = {id=70751,name="Terillod the Devout",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[70763] = {id=70763,name="Worldcarver A'tir",level=70,requiredLevel=70,faction="none",expansion=9,zoneID=13644,mapID=2022,questType="standard"},
[70779] = {id=70779,name="Tarjin's Tales",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,description="You think yourself worthy of the incredible legends and histories of the djaradin? You, who are hardly the size of one of our weapons? Pfft. I doubt you have the stomach to carry the legacy of my people. Prove me wrong, if you can. Seek out dragons, the only worthy rival on these isles. Bring me trophies of your victory over their strongest.",starts={{npcID=196214,x=0.16,y=0.626,mapID=2022}},ends={{npcID=196214,x=0.16,y=0.626,mapID=2022}},coords={x=0.16,y=0.626,source="quest_giver",mapID=2022},questType="standard"},
[70781] = {id=70781,name="Out of the Blue",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13647,mapID=2025,description="Did you see that?! This winged creature just fell from the sky! I don't know what sort of being it is, but it certainly isn't native to the Isles. Wait... I do remember a punchy little goblin asking for directions to the Bluefeather Cliffs just above us. You think she would know anything about it?",starts={{npcID=196392,x=0.504,y=0.674,mapID=2025}},ends={{npcID=183912,x=0.5,y=0.698,mapID=2025}},coords={x=0.504,y=0.674,source="quest_giver",mapID=2025},questType="standard"},
