[71093] = {id=71093,name="Legacy of Tyr: Secrets of the Past",level=70,requiredLevel=70,faction="none",expansion=9,description="To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored. Inconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead. Queen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there. Word is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!",questType="dungeon"},
[71097] = {id=71097,name="A Helping Claw",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,description="Alright, you've charged the artifact. Let's turn it on. And stop giving me that look. Don't pretend like you aren't curious to see if it works. Just give that thing another shake, back away slowly, and let me finish the job.",starts={{npcID=197201,x=0.46,y=0.258,mapID=2024}},ends={{npcID=197201,x=0.46,y=0.258,mapID=2024}},coords={x=0.46,y=0.258,source="quest_giver",mapID=2024},questType="standard"},
[71143] = {id=71143,name="The Horde Slayer",level=10,requiredLevel=10,faction="alliance",expansion=9,description="Wow! Keep it up, soldier! Slay a bit more Horde and you will go down in the record books among the Alliance. But it won't be easy, the Horde have put a bounty on your head, so watch it! For the Alliance!",questType="standard"},
[71144] = {id=71144,name="The Alliance Slayer",level=10,requiredLevel=10,faction="horde",expansion=9,description="Yes! Keep going, keep slaying those Alliance dogs! Slay a bit more Alliance and you may set a new record, . But it won't be easy, the Alliance have put a bounty on your head, so watch it! For the Horde!",questType="standard"},
[71153] = {id=71153,name="WQs, Bonus Objectives and Scenarios Oh My",level=50,requiredLevel=50,faction="none",expansion=9,description="Assist the Tortollan by completing 3 world quests.",questType="standard"},
[71178] = {id=71178,name="Waygate: Shady Sanctuary",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,description="Our expedition reports a dormant stone out in the lush hillsides to the southwest. It's quite a journey, but worth sendin' someone with yer knowledge tae investigate.",starts={{npcID=189066,x=0.472,y=0.902,mapID=2022}},ends={{npcID=189066,x=0.472,y=0.902,mapID=2022}},coords={x=0.472,y=0.902,source="quest_giver",mapID=2022},questType="standard"},
[71226] = {id=71226,name="Kill Rock Snails",level=60,requiredLevel=60,faction="none",expansion=9,zoneID=10534,mapID=1533,description="Help! all these bunnies are eating my flesh! Please, kill them before they kill us all!",questType="standard"},
[71227] = {id=71227,name="Aerial Challenges",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,description="Dragonrider! Your flight prowess has become well known. Come test yourself in Aerial Challenges across the Dragon Isles. Speak to any Bronze Timekeeper to get started.",starts={{npcID=197478,x=0.456,y=0.552,mapID=2112}},ends={{npcID=190326,x=0.628,y=0.74,mapID=2022},{npcID=190473,x=0.47,y=0.856,mapID=2022},{npcID=190519,x=0.418,y=0.672,mapID=2022},{npcID=190551,x=0.232,y=0.842,mapID=2022},{npcID=190667,x=0.554,y=0.412,mapID=2022},{npcID=190753,x=0.732,y=0.34,mapID=2022},{npcID=191121,x=0.862,y=0.358,mapID=2023},{npcID=191165,x=0.808,y=0.722,mapID=2023},{npcID=191247,x=0.256,y=0.55,mapID=2023},{npcID=191422,x=0.598,y=0.354,mapID=2023},{npcID=192555,x=0.576,y=0.75,mapID=2025},{npcID=193651,x=0.572,y=0.668,mapID=2025},{npcID=193911,x=0.376,y=0.49,mapID=2025},{npcID=193951,x=0.602,y=0.416,mapID=2025},{npcID=194348,x=0.394,y=0.762,mapID=2025},{npcID=192886,x=0.166,y=0.494,mapID=2024},{npcID=193027,x=0.422,y=0.568,mapID=2024}},coords={x=0.456,y=0.552,source="quest_giver",mapID=2024},questType="standard"},
[71242] = {id=71242,name="Supporting the Storm Researchers",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="This looks like a large cluster of overflowing power from creatures within the Primalist Storm. There's bound to be a researcher in Valdrakken who'll want this.",ends={{npcID=196516,x=0.38,y=0.374,mapID=2112},{npcID=196516,x=0.356,y=0.598,mapID=2151}},questType="standard"},
