[72395] = {id=72395,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=193006,x=0.13,y=0.492,mapID=2024}},ends={{npcID=193006,x=0.13,y=0.492,mapID=2024}},coords={x=0.13,y=0.492,source="quest_giver",mapID=2024},questType="standard"},
[72405] = {id=72405,name="An Unlikely Informant",level=50,requiredLevel=50,faction="alliance",expansion=9,zoneID=12,mapID=37,description="This is a top secret mission, . We've had a break in. A powerful historical artifact was stolen from the Keep... and it looks like the Defias Brotherhood is to blame. We caught one thief, but the other got away. But I don't like it, ... my gut tells me there's more. I've called in a... specialist on the Brotherhood. Meet us in the basement of the Lion's Pride Inn in Goldshire.",starts={{npcID=198884,x=0.874,y=0.306,mapID=84}},ends={{npcID=198896,x=0.444,y=0.662,mapID=37}},coords={x=0.874,y=0.306,source="quest_giver",mapID=37},questType="standard"},
[72428] = {id=72428,name="Hornswog Hoarders",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="It's no secret that the hornswogs in these lands have a fascination for gems, jewels, and all things shiny. Why, even the other day I found a very rare jewel in some hornswog droppings! Well, it might not be the most appealing task, but it seems the hornswog have a habit of not only collecting, but also consuming valuables.",starts={{npcID=191001,x=0.368,y=0.626,mapID=2112}},ends={{npcID=191001,x=0.368,y=0.626,mapID=2112}},coords={x=0.368,y=0.626,source="quest_giver",mapID=2112},questType="standard"},
[72434] = {id=72434,name="Ruby Lifeshrine Loop",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13644,mapID=2022,description="They say I'm not big enough to fly some of these courses yet. But I can still watch others do it. You should race! Then I can watch you race.",questType="standard"},
[72452] = {id=72452,name="Go with Honor, Friend",level=50,requiredLevel=50,faction="alliance",expansion=9,zoneID=1519,mapID=84,description="This mission ended up being far more than any of us expected, , and you did very well. I shudder to think of what would have happened without you here. Some time back, the King commissioned a set of armor be made. Armor to adorn our greatest heroes. You have proven yourself more than deserving of such honor. Meet me in the Valley of Heroes, .",starts={{npcID=198983,x=0.366,y=0.51,mapID=37}},ends={{npcID=65153,x=0.25,y=0.95,mapID=37},{npcID=65153,x=0.692,y=0.83,mapID=84}},coords={x=0.366,y=0.51,source="quest_giver",mapID=84},questType="standard"},
[72462] = {id=72462,name="A People in Need of Healing",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14525,description="It is strange, . Despite the years of peace, I am restless. Despite having the Horde and my son, I am lonely. You feel the same, don't you? I see it in your eyes, and in the eyes of many orcs. I feel perhaps that while we have found our way on Azeroth, we have lost our way as orcs. Come with me. I wish to speak with an old friend about these troubles, and I would like you by my side.",starts={{npcID=3144,x=0.49,y=0.722,mapID=85}},ends={{npcID=200244,x=0.544,y=0.784,mapID=85}},coords={x=0.49,y=0.722,source="quest_giver",zoneID=1637},questType="standard"},
[72463] = {id=72463,name="Galgar's Cactus Apple Surprise...",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="Galgar . Will you honor her request?>",starts={{npcID=200760,x=0.498,y=0.602,mapID=1}},ends={{npcID=9796,x=0.43,y=0.626,mapID=1},{npcID=9796,x=0.428,y=0.672,mapID=1}},coords={x=0.498,y=0.602,source="quest_giver",mapID=1},questType="standard"},
[72464] = {id=72464,name="The Kosh'harg",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14525,description="The Kosh'harg will be held in Razor Hill. Go'el and Eitrigg are gathering the clans as we speak. We will have to part ways for now. You must begin mentally preparing yourself for the om'gora--the rite of honor. It is my task to make sure it is a worthy challenge, even for you. I will call our wind riders to carry my family to the Kosh'harg. You may travel with them, or meet us there.",starts={{npcID=200244,x=0.544,y=0.784,mapID=85}},ends={{npcID=199148,x=0.522,y=0.43,mapID=1}},coords={x=0.544,y=0.784,source="quest_giver",zoneID=1637},questType="standard"},
[72465] = {id=72465,name="The Blessing of the Land",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="To earn the blessing of the land, a young orc must learn respect for the spirits that dwell alongside us. If we do not live in balance with the elements and life around us, it can lead to calamity. I will call to the spirits, and they will guide us to where your aid is needed. It is up to you to complete the task before you.",starts={{npcID=199148,x=0.522,y=0.43,mapID=1}},ends={{npcID=199165,x=0.406,y=0.268,mapID=1}},coords={x=0.522,y=0.43,source="quest_giver",mapID=1},questType="standard"},
[72466] = {id=72466,name="The Spirit of Thunder Ridge",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="Life can only thrive when a delicate balance is maintained. The arrival of your people and the humans was but the first link in the chain that led to desolation. You yourself are not to blame, but you can be the force that restores what once was. Dive into the waters below and recover the seeds buried in the silt. They are a memory of the ancient forest that once grew in harmony with my people. Beware, the elements are not at peace here.",starts={{npcID=199165,x=0.406,y=0.268,mapID=1}},ends={{npcID=199148,x=0.522,y=0.43,mapID=1}},coords={x=0.406,y=0.268,source="quest_giver",mapID=1},questType="standard"},
[72467] = {id=72467,name="The Blessing of the Clan",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="To earn the blessing of the clan, a young orc must learn that the clan is only as strong as its members. Prove your strength, and worth, to the living orcs. Since you were not born into a clan, you must first choose a clan to champion, and be accepted by the clan's chieftain. The chieftains have gathered in the barracks. Join a clan, and complete the task given to you.",starts={{npcID=199148,x=0.522,y=0.43,mapID=1}},ends={{npcID=199148,x=0.522,y=0.43,mapID=1}},coords={x=0.522,y=0.43,source="quest_giver",mapID=1},questType="standard"},
[72474] = {id=72474,name="Tracking a Killer",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=6451,mapID=1,description="Gor'krosh, the Long Knives, has been terrorizing the Valley of Trials for weeks. Orcs have been going missing, and many of our young trainees have been injured. The peons took to calling the mysterious attacker the Long Knives because the few bodies we have found all have long, terrible gashes across their backs. They're terrified, and refusing to work! We have no idea who or what Gor'krosh really is, but they are clearly very dangerous. Please, find this monster and end this madness!",starts={{npcID=10176,x=0.432,y=0.688,mapID=1},{npcID=10176,x=0.452,y=0.686,mapID=1}},ends={{npcID=10176,x=0.432,y=0.688,mapID=1},{npcID=10176,x=0.452,y=0.686,mapID=1}},coords={x=0.432,y=0.688,source="quest_giver",mapID=1},questType="standard"},
[72475] = {id=72475,name="Cornering Gor'krosh",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=6451,mapID=1,description="If Gor'krosh is a truly a raptor, you should be able to track it down just like any other animal. See if you can find its trail. We know it's been around here recently. Corner it in its lair and end this once and for all! Make sure you return to Razor Hill straight away once you make the kill. The Farseer will need proof of the deed. Thank you, . May the spirits guide your blade. Lok-tar!",starts={{npcID=10176,x=0.432,y=0.688,mapID=1},{npcID=10176,x=0.452,y=0.686,mapID=1}},ends={{npcID=199148,x=0.522,y=0.43,mapID=1}},coords={x=0.432,y=0.688,source="quest_giver",mapID=1},questType="standard"},
[72476] = {id=72476,name="The Blessing of the Ancestors",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="The blessing of the ancestors is meant to teach young orcs that the living owe everything to those that came before. We must honor the ancestors, seek their wisdom, and live up to their expectations. Your task is to craft an offering worthy of the honored dead, and worthy of being the centerpiece at the offering stone of the first Kosh'harg of Azeroth! You must put all of your energy into its construction, or it will not be enough. Cook Torka will guide you. The ancestors will be watching.",starts={{npcID=199148,x=0.522,y=0.43,mapID=1}},ends={{npcID=199383,x=0.508,y=0.428,mapID=1}},coords={x=0.522,y=0.43,source="quest_giver",mapID=1},questType="standard"},
[72477] = {id=72477,name="Orcish Groceries",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="In here is a recipe for the traditional feast left for the ancestors at the Kosh'harg by the clans. We're going to have to substitute some ingredients that, you know, no longer exist... But it will for the better! We'll bring some Azeroth flair to this traditional dish! I will teach you each piece of the recipe, but it will be up to you to gather the ingredients and actually cook it. Orc traders have come from all over, so you should be able to find everything you need right here in Razor Hill.",starts={{npcID=199383,x=0.508,y=0.428,mapID=1}},coords={x=0.508,y=0.428,source="quest_giver",mapID=1},questType="standard"},
[72478] = {id=72478,name="Honor and Glory",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=3518,mapID=107,description="You have successfully completed the om'gora! Congratulations, . Now it is time for us to celebrate! We have prepared a feast for all in attendance, in your honor! Go, revel in the glory you have earned. Enjoy yourself. If any of these orcs get out of line, remind them why you were the one who was chosen to complete the new rite first!",starts={{npcID=199148,x=0.522,y=0.43,mapID=1}},ends={{npcID=200437,x=0.522,y=0.434,mapID=1}},coords={x=0.522,y=0.43,source="quest_giver",mapID=107},questType="standard"},
[72479] = {id=72479,name="Aka'magosh",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="The Kosh'harg has been a great success, in no small part thanks to you, . All that is left is for Aggra to perform the ceremony to bring the festival to an official close. I wish to speak to the crowd before we all disperse again, on some things long overdue in being said.",starts={{npcID=200437,x=0.522,y=0.434,mapID=1}},ends={{npcID=200617,x=0.522,y=0.43,mapID=1}},coords={x=0.522,y=0.434,source="quest_giver",mapID=1},questType="standard"},
[72481] = {id=72481,name="The Waking Shores Tour",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2022,description="And what is the most fun about dragonriding? Races! My bronze colleagues have mapped out race courses all over the Dragon Isles. It is such a varied and dynamic landscape that it just begs to be explored at top speed. If you find yourself near one of our race courses in The Waking Shores , why not give it a go?",starts={{npcID=193411,x=0.732,y=0.52,mapID=2022}},ends={{npcID=193411,x=0.732,y=0.52,mapID=2022}},coords={x=0.732,y=0.52,source="quest_giver",mapID=2022},questType="standard"},
[72482] = {id=72482,name="The Waking Shores Advanced Tour",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13647,mapID=2025,description="Now that you've flown the basic courses all over the Dragon Isles and proved your ability, how about a new challenge? The advanced race courses are similar to the standard courses you have flown, but many have adjusted flight paths or extra obstacles to test your skill. Let us start with the courses in the Waking Shores !",starts={{npcID=193411,x=0.732,y=0.52,mapID=2022},{npcID=199120,x=0.46,y=0.63,mapID=2025}},ends={{npcID=193411,x=0.732,y=0.52,mapID=2022}},coords={x=0.732,y=0.52,source="quest_giver",mapID=2025},questType="standard"},
[72483] = {id=72483,name="The Ohn'ahran Plains Tour",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Ah, the Ohn'ahran Plains . Wide open spaces, gusting winds, endless vistas... and more race courses! Just as in the Waking Shores, if you find any of my bronze colleagues, speak to them about their race course.",starts={{npcID=193411,x=0.732,y=0.52,mapID=2022}},ends={{npcID=199118,x=0.88,y=0.362,mapID=2023}},coords={x=0.732,y=0.52,source="quest_giver",mapID=2023},questType="standard"},
[72484] = {id=72484,name="The Ohn'ahran Plains Advanced Tour",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13645,mapID=2023,description="The advanced courses should be more challenging, but I am sure it is nothing you cannot handle! My bronze colleagues have set up advanced courses in the Ohn'ahran Plains that have a few obstacles and surprises thrown in them. You can also compete against your own best times! Good luck!",starts={{npcID=193411,x=0.732,y=0.52,mapID=2022}},ends={{npcID=199118,x=0.88,y=0.362,mapID=2023}},coords={x=0.732,y=0.52,source="quest_giver",mapID=2023},questType="standard"},
[72485] = {id=72485,name="The Azure Span Tour",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,description="Azure Span courses are a unique experience. Their high peaks, snowy terrain, and dense forest present plenty of interesting obstacles--and challenges! While you are there, seek out my bronze colleagues and give their courses a try!",starts={{npcID=199118,x=0.88,y=0.362,mapID=2023}},ends={{npcID=199119,x=0.632,y=0.136,mapID=2024}},coords={x=0.88,y=0.362,source="quest_giver",mapID=2024},questType="standard"},
[72486] = {id=72486,name="The Azure Span Advanced Tour",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,description="The advanced courses in the Azure Span are designed to elevate your dragon riding skills to new heights! Just... make sure you don't fall from them! When you're ready, seek out my bronze colleagues and fly those courses!",starts={{npcID=199118,x=0.88,y=0.362,mapID=2023}},ends={{npcID=199119,x=0.632,y=0.136,mapID=2024}},coords={x=0.88,y=0.362,source="quest_giver",mapID=2024},questType="standard"},
[72487] = {id=72487,name="The Thaldraszus Tour",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13647,mapID=2025,description="Thaldraszus . It is the home of the Seat of the Aspects and much of dragonkind's history. It is also home to soaring heights and steep deep ravines just waiting to be flown over! As before, my bronze colleagues have set up race courses in Thaldraszus to fly while you explore. Why not give them a try and complete your Dragon Isles racing tour?",starts={{npcID=199119,x=0.632,y=0.136,mapID=2024}},ends={{npcID=199120,x=0.46,y=0.63,mapID=2025}},coords={x=0.632,y=0.136,source="quest_giver",mapID=2025},questType="standard"},
[72488] = {id=72488,name="The Thaldraszus Advanced Tour",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13647,mapID=2025,description="Once more to Thaldraszus with its peaks and valleys and courses ready and waiting for you to race! Seek out my bronze colleagues to fly the advanced courses and finish your racing tour of the Dragon Isles!",starts={{npcID=199119,x=0.632,y=0.136,mapID=2024}},ends={{npcID=199120,x=0.46,y=0.63,mapID=2025}},coords={x=0.632,y=0.136,source="quest_giver",mapID=2025},questType="standard"},
[72512] = {id=72512,name="A Whispering Breeze",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13982,mapID=2023,description="Godoloto cocks her head quizzically, nods at you, and finally holds your gaze. After a long moment, she casts her eyes up towards the sky... and the mountain just beside Maruukai. You sense that she wants you to travel up to Ohn'ahra 's Roost.>",starts={{npcID=190022,x=0.51,y=0.622,mapID=2023}},ends={{npcID=191248,x=0.576,y=0.318,mapID=2023}},coords={x=0.51,y=0.622,source="quest_giver",mapID=2023},questType="standard"},
[72513] = {id=72513,name="Our Destiny",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Evoker! You might have felt a disturbance just recently. Ebyssian and I have begun to unbind the ancient siphons that were extracting the black dragonflight essence from dracthyr. I suspect that only the fully trained evokers like yourself are tuned enough to feel the change. There is more, though. Please, come join Ebyssian and myself at the High Creche in the Forbidden Reach. We have a dragon to unchain.",ends={{npcID=199135,x=0.586,y=0.684,mapID=2151}},questType="standard"},
[72514] = {id=72514,name="The High Creche",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Have you felt it? We have already started bringing the barrier down. This prison for Adamanthia held so much power. And now I can augment again! A fully trained evoker was always intended to empower their allies, as much as healing or devastation. I remember that now... and more. I am starting to remember who this imprisoned black dragon was... who she was to all dracthyr. Please, $p, help me remove these shackles.",starts={{npcID=199135,x=0.586,y=0.684,mapID=2151}},ends={{npcID=199141,x=0.586,y=0.684,mapID=2151}},coords={x=0.586,y=0.684,source="quest_giver",mapID=2151},questType="standard"},
[72515] = {id=72515,name="Augmenting a Dragon",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Adamanthia ! She has been imprisoned for ages, trapped in torment. While the dracthyr slept, she suffered. I can only hope she has not given in to Deathwing's madness during her long imprisonment. The passage of time may have shattered her mind. Be ready, champion. Should she lash out, aid Ebyssian . Augment his abilities, so he can subdue Adamanthia instead of slaying her. She has earned a chance. We must give it to her.",starts={{npcID=199141,x=0.586,y=0.684,mapID=2151}},ends={{npcID=199141,x=0.586,y=0.684,mapID=2151}},coords={x=0.586,y=0.684,source="quest_giver",mapID=2151},questType="standard"},
