[72545] = {id=72545,name="Creche Fallen",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="This is my failure, $p. I led these dracthyr here. They knew death was a possibility, but they also trusted me to be there for them. I should have been down there, clearing the ruins, not up here trawling through books. I need you to retrieve their horn signets. We need to give them honors.",starts={{npcID=199531,x=0.55,y=0.358,mapID=2151}},ends={{npcID=199531,x=0.55,y=0.358,mapID=2151}},coords={x=0.55,y=0.358,source="quest_giver",mapID=2151},questType="standard"},
[72546] = {id=72546,name="Academic Assistance",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="! I've made a breakthrough with tha Winterpelt dialect. Ya helped get tha ball rollin' on this, so I felt like I ought ta keep ya apprised of the situation. Meet me in Theron's Watch and I'll tell ya all about it.",ends={{npcID=189401,x=0.654,y=0.16,mapID=2024}},questType="standard"},
[72547] = {id=72547,name="Academic Acquisitions",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="I'll head up tae the village an' give 'em the bad news--or try. Winterpelt's a right tricky dialect tae learn. I need ye tae get out there an' find me some furbolg writin' samples tae study if we ever hope tae communicate properly. The Primalists've wiped out or converted most o' the remainin' furbolg in the Span, so go shake 'em down until whate'er cultural artifacts they have drop out. I'll need at least five tae start, but bring me as many as ye can, and I'll keep teachin' ye what I learn.",starts={{npcID=189401,x=0.654,y=0.16,mapID=2024}},ends={{npcID=201065,x=0.668,y=0.126,mapID=2024}},coords={x=0.654,y=0.16,source="quest_giver",mapID=2024},questType="standard"},
[72548] = {id=72548,name="Dragonflight (60-69) E",level=60,requiredLevel=60,faction="none",expansion=9,questType="standard"},
[72549] = {id=72549,name="Dragonflight (60-69) E",level=60,requiredLevel=60,faction="none",expansion=9,questType="standard"},
[72550] = {id=72550,name="Dragonflight (60-69) E",level=60,requiredLevel=60,faction="none",expansion=9,questType="standard"},
[72551] = {id=72551,name="A Living History",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="The Winterpelt finally trust us enough to ask for aid. We must nurture this trust so we may one day clasp their paws in friendship! This Winterpelt, Jyrra of the, uh, Fuzzy Feet, says their elders went into hiding during the Primalist attack on their village. I don't yet understand their language, but it seems the elders left markers to help the clan find them later. It's time to let the Winterpelt elders know it's safe to come home. Will you convey this message? It seems a simple enough task.",starts={{npcID=199266,x=0.668,y=0.13,mapID=2024}},ends={{npcID=199271,x=0.574,y=0.21,mapID=2024}},coords={x=0.668,y=0.13,source="quest_giver",mapID=2024},questType="standard"},
[72552] = {id=72552,name="Gathering Together",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="I haven't heard an outsider speak our tongue. Your grasp is a bit basic... But only a friend of the clan would speak it at all! I am Elder Mhaz . If it is safe to return home, we should set off soon. But many of us are weak with sadness of the heart--and grumbling of the stomach. I would not put you at risk gathering fresh meat, but could you gather roots for us? We have already gathered ones that are close. I hope this comfort food will lift our spirits enough to return!",starts={{npcID=199271,x=0.574,y=0.21,mapID=2024}},ends={{npcID=199271,x=0.574,y=0.21,mapID=2024}},coords={x=0.574,y=0.21,source="quest_giver",mapID=2024},questType="standard"},
[72553] = {id=72553,name="More Effort, More Reward",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="We're not sad. We're starving. That's the truth of it. A few tasty roots won't be enough. Elder Mhaz doesn't recognize strength, but I do. It should be (100)-trivial for you to bring us some fresh meat! The worms to the east should be easy prey. Please, bring back what you can carry!",starts={{npcID=199272,x=0.574,y=0.208,mapID=2024}},ends={{npcID=199272,x=0.574,y=0.208,mapID=2024}},coords={x=0.574,y=0.208,source="quest_giver",mapID=2024},questType="standard"},
[72554] = {id=72554,name="Break Him",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="You handled those little worms with such ease! However... Saza hasn't come back. The giant worm, Icebreaker , has been hunting us for weeks. It took two of our elders while we gathered food and injured me when I tried to avenge them. And now, with Saza missing, I fear the worst. Find Saza , and get rid of that worm!",starts={{npcID=199272,x=0.574,y=0.208,mapID=2024}},ends={{npcID=199272,x=0.574,y=0.208,mapID=2024}},coords={x=0.574,y=0.208,source="quest_giver",mapID=2024},questType="standard"},
[72555] = {id=72555,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=9,questType="standard"},
[72556] = {id=72556,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=9,questType="standard"},
[72557] = {id=72557,name="Dragonflight (70) E",level=70,requiredLevel=70,faction="none",expansion=9,questType="standard"},
[72558] = {id=72558,name="Our Honored Ancestors",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="It is time to take the next step to understanding the Winterpelt. That step is a spiritual one. They look to their ancestors for advice as they choose their path forward. We can learn from them too. But the Winterpelt rite to call their ancestors is... intricate. And long. It would be rude to copy their ritual anyway. We'll do it our way with Rustpine Spiritspeaker incense. Come! Let us reveal their ancestors' wisdom and learn more about our new friends!",starts={{npcID=199267,x=0.66,y=0.126,mapID=2024}},ends={{npcID=199267,x=0.66,y=0.126,mapID=2024}},coords={x=0.66,y=0.126,source="quest_giver",mapID=2024},questType="standard"},
[72559] = {id=72559,name="History Heist",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="When the Primalists raided our village, they took more than our lives; they stole the heart of our community--our priceless historical documents! I will not stand for records of our traditions, rituals, and rich history taken from us! We still have lessons to learn from them. Please, recover them from those looting Primalist scouts so they can be preserved!",starts={{npcID=199299,x=0.67,y=0.118,mapID=2024}},ends={{npcID=199267,x=0.66,y=0.126,mapID=2024}},coords={x=0.67,y=0.118,source="quest_giver",mapID=2024},questType="standard"},
