[72586] = {id=72586,name="Additional Academic Acquisitions",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="Keep 'em comin'! The more examples o' furbolg writin' ye collect for me tae cross reference, the better.",ends={{npcID=201065,x=0.668,y=0.126,mapID=2024}},questType="standard"},
[72587] = {id=72587,name="Astonishing Academic Acquisitions",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="Where did ya get that beauty? Tha Primalists seem a lot more interested in destroying civilizations than preserving their history, which makes a find like this all tha more precious. I'll get out me good rubbing stick for this one!",ends={{npcID=201065,x=0.668,y=0.126,mapID=2024}},questType="standard"},
[72588] = {id=72588,name="Primalist Pillagers",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="I'm startin' tae grasp the basics of Winterpelt, but what I'm pickin' up is grim. Seems a band of Winterpelt foragers fell afoul o' the nearby Primalists. The winters here are as harsh as any in Dun Morogh, an' the supplies they were gatherin' will be sorely missed. Why don't ya see about recoverin' what ye can. With prejudice, if ye don't mind.",starts={{npcID=189401,x=0.654,y=0.16,mapID=2024}},ends={{npcID=189401,x=0.654,y=0.16,mapID=2024}},coords={x=0.654,y=0.16,source="quest_giver",mapID=2024},questType="standard"},
[72589] = {id=72589,name="Honor Their Sacrifice",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="There's nothin' we can do for the foragers the Primalists killed, but we can at least try an' provide some closure tae their kin. See if ye can find anythin' of a personal nature on the fallen. I'm sure the Winterpelt will appreciate whatever ye can bring them.",starts={{npcID=189401,x=0.654,y=0.16,mapID=2024}},ends={{npcID=189401,x=0.654,y=0.16,mapID=2024}},coords={x=0.654,y=0.16,source="quest_giver",mapID=2024},questType="standard"},
[72590] = {id=72590,name="Ursol's Wisdom",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="We have strayed from wise Ursol's path, trading focus for obsession and contemplation for fear. Gather cones from the mighty Rustpines. As their roots stretch deep into the earth, take strength from the waters, reach into the winds, and are ripened by fire, they will be a symbol of our renewed commitment to true balance. Take to the skies on that drake of yours and you should be able to gather enough. The upper branches are the best place to find them. Offer them to Ursol at his nearby shrine.",starts={{npcID=189394,x=0.66,y=0.106,mapID=2024}},ends={{npcID=189394,x=0.66,y=0.106,mapID=2024}},coords={x=0.66,y=0.106,source="quest_giver",mapID=2024},questType="standard"},
[72591] = {id=72591,name="A Debt That Must Be Paid",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description=", I have heard you cultivated good relations with the centaur of the Ohn'ahran Plains . I would like to ask a favor. Baine left for the plains a few days ago in search of a group of missing tauren. I offered to accompany him, but he insisted on going alone. The tauren of Thunder Bluff have a long and bloody history with the centaur of Kalimdor, as does Baine. While the Maruuk centaur are unrelated, I still have my concerns. Your presence could help smooth tensions. I hope.",starts={{npcID=202656,x=0.508,y=0.584,mapID=2112}},ends={{npcID=199323,x=0.666,y=0.386,mapID=2023}},coords={x=0.508,y=0.584,source="quest_giver",mapID=2023},questType="standard"},
[72592] = {id=72592,name="Scars from the Past",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="A tribe of tauren came to the Dragon Isles led by a close friend of mine, Bovan Windtotem. No one has heard from them since they entered these plains. If they have gone missing, then I must find them. Unfortunately, I underestimated the size of this place. You have an existing relationship with the centaur. Will you go speak with them and see if they have any information on Bovan or his tribe? Perhaps they can help narrow down my search.",starts={{npcID=199323,x=0.666,y=0.386,mapID=2023}},ends={{npcID=199323,x=0.666,y=0.386,mapID=2023}},coords={x=0.666,y=0.386,source="quest_giver",mapID=2023},questType="standard"},
[72593] = {id=72593,name="A Tomul-tuous Beginning",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Since the dragons returned, we've seen an overwhelming number of outsiders passing through the plains. Normally we keep a close eye on our borders, but their sheer numbers, combined with the Nokhud threat, have made it difficult to track them. One scout reported a group of outsiders that matched your description traveling along the eastern road. We should start our search there. As for your friend, my khan gave me a command. A huffy companion won't stop me from carrying it out.",starts={{npcID=199330,x=0.666,y=0.386,mapID=2023}},ends={{npcID=202707,x=0.694,y=0.476,mapID=2023}},coords={x=0.666,y=0.386,source="quest_giver",mapID=2023},questType="standard"},
[72594] = {id=72594,name="Delivering Bad News",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="As soon as we arrived, Baine was whisked away. Bovan is still missing, so he is speaking to someone named Tagar. Of course I've been left out here in the cold. It seems they still don't trust me. In any case, you should go in and speak with the tauren. Take the items you found and try to identify who they belonged to. At the very least, you can let the families know what we've discovered so far. But... be gentle, . For some of them, this may be the worst day of their lives.",starts={{npcID=200492,x=0.732,y=0.55,mapID=2023}},ends={{npcID=200831,x=0.728,y=0.558,mapID=2023}},coords={x=0.732,y=0.55,source="quest_giver",mapID=2023},questType="standard"},
[72595] = {id=72595,name="The Search for Bovan Windtotem",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="According to this survivor, the centaur took them completely by surprise. Bovan led many of the braves against the centaur, hoping to buy time for the others to escape. He succeeded, but Bovan and most of the braves have not returned. We must find him, . I need you to search the surrounding area. If you find survivors, tell them to make their way back here. If you find fallen tauren... take something recognizable to bring back to their families.",starts={{npcID=202707,x=0.694,y=0.476,mapID=2023}},ends={{npcID=202707,x=0.694,y=0.476,mapID=2023}},coords={x=0.694,y=0.476,source="quest_giver",mapID=2023},questType="standard"},
[72597] = {id=72597,name="Ursoc's Strength",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="It has been many years since we last offered sacrifices to mighty Ursoc, but we will need his blessing if we are to restore balance among our people. His shrine is hidden in the mountains to the east where few would stumble upon it by chance.",starts={{npcID=189394,x=0.66,y=0.106,mapID=2024}},ends={{npcID=189394,x=0.66,y=0.106,mapID=2024}},coords={x=0.66,y=0.106,source="quest_giver",mapID=2024},questType="standard"},
[72598] = {id=72598,name="Words of the Winterpelt",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="The Winterpelt Chief sent word while ye were out that he wanted tae speak with ye again. And, thanks tae all the work ye been puttin' in, we could actually understand the message! We're on the cusp o' somethin' great here, . Think of it... The trade routes we could establish! The cultural exchange that could take place! The papers I could publish! Well? What are ye standin' around for? Go see what he wants!",starts={{npcID=201065,x=0.668,y=0.126,mapID=2024}},ends={{npcID=189394,x=0.66,y=0.106,mapID=2024}},coords={x=0.668,y=0.126,source="quest_giver",mapID=2024},questType="standard"},
[72599] = {id=72599,name="Joint Rescue Operation",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Tomul says the attacks on the Windtotem were carried out by an enemy clan known as the Nokhud. Just down this road is their closest outpost, and the most likely location where tauren prisoners would be taken. The task is simple--rescue the captives. We do not know how many there are, or how long they have been here, so we must hurry. I speak from experience when I say centaur do not keep their captives for long.",starts={{npcID=200932,x=0.808,y=0.576,mapID=2023}},ends={{npcID=200932,x=0.808,y=0.576,mapID=2023},{npcID=200939,x=0.872,y=0.516,mapID=2023}},coords={x=0.808,y=0.576,source="quest_giver",mapID=2023},questType="standard"},
[72600] = {id=72600,name="A Proper Shikaar Send-Off",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="We're here to rescue the captive tauren, but I have a personal request. The place we are assaulting was once my home. The Nokhud took over after a surprise attack during the civil war. Take these Shikaar banners . When you kill a Nokhud or one of their allies, plant a banner on their corpse. I want to send a message--if they continue to occupy our home, they will pay in blood.",starts={{npcID=200933,x=0.808,y=0.576,mapID=2023}},ends={{npcID=200938,x=0.872,y=0.514,mapID=2023}},coords={x=0.808,y=0.576,source="quest_giver",mapID=2023},questType="standard"},
[72601] = {id=72601,name="Bovan's Last Hope",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="If Bovan is not here, the Nokhud could have taken him anywhere. We might have one last chance to find him, but it's a long shot. We still have Bovan's necklace. One of the Ohn'ir mystics might be able to use it to help divine his location. I've only heard about this ritual, so I have no idea if it will work. Go to the Ohn'iri Springs and look for Boku. I'm sure he will help us. Baine and I will make sure the tauren we rescued get back safely. We'll meet you at the Ohn'iri Springs.",starts={{npcID=200938,x=0.872,y=0.514,mapID=2023}},ends={{npcID=199409,x=0.566,y=0.738,mapID=2023}},coords={x=0.872,y=0.514,source="quest_giver",mapID=2023},questType="standard"},
[72602] = {id=72602,name="Optimistic Mystic",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="I'm sure I can find this Bovan Windtotem--but I will need a few items from you. First, I need a selection of flowers that grow at the base of the springs. They have the specific properties we are looking for. Next, I require the heart of a salamanther. A stronger heart will better our chances--look for the strongest you can find! I can gather the rest of the materials on my own.",starts={{npcID=199409,x=0.566,y=0.738,mapID=2023}},ends={{npcID=199409,x=0.566,y=0.738,mapID=2023}},coords={x=0.566,y=0.738,source="quest_giver",mapID=2023},questType="standard"},
[72603] = {id=72603,name="What Words Are Worth",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Let me just grind these flowers and... there we are, all ready! Take these items and place them in the incense burner. Together with Bovan's necklace, I can entreat Ohn'ahra to help us find him. With luck, she will give us a vision.",starts={{npcID=199409,x=0.566,y=0.738,mapID=2023}},ends={{npcID=201424,x=0.568,y=0.716,mapID=2023}},coords={x=0.566,y=0.738,source="quest_giver",mapID=2023},questType="standard"},
[72604] = {id=72604,name="Desperate Rescue",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="I should have known I could not trust the centaur. They may provide token amounts of aid, but they would never risk themselves for us. Let us focus on the matter at hand. We cannot allow Bovan to remain in centaur captivity! I will set out immediately for Nokhudon Hold. Meet me there as quickly as you can.",starts={{npcID=201424,x=0.568,y=0.716,mapID=2023}},ends={{npcID=201488,x=0.38,y=0.34,mapID=2023}},coords={x=0.568,y=0.716,source="quest_giver",mapID=2023},questType="standard"},
[72605] = {id=72605,name="Saving Bovan Windtotem",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Time is against us, . We must find Bovan as quickly as possible. This hold is teeming with centaur. Our search will go faster if we split up--and it will be easier to slip by the patrols. Take one of these potions I brought. It should help you go undetected, but beware of the Nokhud wardogs. If Tomul spoke correctly, they will sniff you out. Search the area for Bovan. If you find him, get him out. Do not wait for me.",starts={{npcID=201488,x=0.38,y=0.34,mapID=2023}},ends={{npcID=201496,x=0.332,y=0.43,mapID=2023}},coords={x=0.38,y=0.34,source="quest_giver",mapID=2023},questType="standard"},
[72606] = {id=72606,name="See Red",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Nokhud. Gelkis. Magram. Kolkar. They are all the same... They plague the land. They murder my people. No more! I will end this centaur threat. Here! Now!",starts={{npcID=201516,x=0.332,y=0.426,mapID=2023}},ends={{npcID=203204,x=0.331,y=0.42,mapID=2023}},coords={x=0.332,y=0.426,source="quest_giver",mapID=2023},questType="standard"},
[72607] = {id=72607,name="Old Hatreds",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="I will not leave... until Jamoku pays... for what he has done... I will avenge Bovan... no matter the cost...",starts={{npcID=203204,x=0.331,y=0.42,mapID=2023}},ends={{npcID=201528,x=0.332,y=0.428,mapID=2023}},coords={x=0.331,y=0.42,source="quest_giver",mapID=2023},questType="standard"},
[72609] = {id=72609,name="Case Closed",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="You are lucky we arrived when we did. We intercepted the Nokhud reinforcements about to flank you during your fight with Jamoku. We lost two of our number in that battle. Their bodies have already been recovered. Bovan's is the last. The Nokhud will not take long to rally and hunt us down. We must leave now. Head to Toghusuq Village, where the tauren are encamped. We will meet you there.",starts={{npcID=201530,x=0.334,y=0.428,mapID=2023}},ends={{npcID=201529,x=0.726,y=0.56,mapID=2023}},coords={x=0.334,y=0.428,source="quest_giver",mapID=2023},questType="standard"},
[72611] = {id=72611,name="Letting Go",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="The Shikaar lost two of their own during the battle. All of Tomul's reinforcements... they volunteered to help, of their own will. I... have much to consider. After speaking with the Shikaar, we decided to honor our dead together. We have blended our funerary rites into one ceremony for this occasion. We would be honored if you would stay and participate.",starts={{npcID=201566,x=0.726,y=0.56,mapID=2023}},ends={{npcID=201566,x=0.726,y=0.56,mapID=2023}},coords={x=0.726,y=0.56,source="quest_giver",mapID=2023},questType="standard"},
