[72644] = {id=72644,name="An Urgent Matter",level=50,requiredLevel=50,faction="alliance",expansion=9,zoneID=1519,mapID=84,description="Hello . I was told to give you letter. The messenger mentioned it was urgent. The crest on it seems to be from SI:7. I would read it right away if I were you.",starts={{npcID=126332,x=0.522,y=0.136,mapID=84}},ends={{npcID=198884,x=0.874,y=0.306,mapID=84}},coords={x=0.522,y=0.136,source="quest_giver",mapID=84},questType="standard"},
[72662] = {id=72662,name="Resupplying Supplies",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="The Nokhud have been striking at outsiders crossing into the plains. This is no doubt their handiwork. This survivor says that most of their food supplies were destroyed in the ambush. We should try to help out. Let's collect meat from the plentiful game around the Watering Hole. That should be enough to cover their immediate needs.",starts={{npcID=202706,x=0.694,y=0.476,mapID=2023}},ends={{npcID=202706,x=0.694,y=0.476,mapID=2023}},coords={x=0.694,y=0.476,source="quest_giver",mapID=2023},questType="standard"},
[72663] = {id=72663,name="Pinewood Trail",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="If Bovan is not dead, and he is not here, then either he is still out there... or he has been captured. Given Tomul's message, I fear it's the latter. The Windtotem are safe for now, but with an attack possible at any moment, they can't spare any braves to go after Bovan. It looks like it is up to us. Let us head to Pinewood Post.",starts={{npcID=200831,x=0.728,y=0.558,mapID=2023}},ends={{npcID=200932,x=0.808,y=0.576,mapID=2023}},coords={x=0.728,y=0.558,source="quest_giver",mapID=2023},questType="standard"},
