[72712] = {id=72712,name="The Best We Have",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="I am glad you're here, $p. The storms have cleared and the creches are open. Now is the time to strike! I'm leading a team of scouts further into the Reach. When you're ready to depart, speak with Talon Damos . He's acting as my second-in-command. The dracthyr he leads will be accompanying us on our next reconnaissance mission.",starts={{npcID=199532,x=0.326,y=0.604,mapID=2151}},ends={{npcID=200403,x=0.55,y=0.372,mapID=2151}},coords={x=0.326,y=0.604,source="quest_giver",mapID=2151},questType="standard"},
[72713] = {id=72713,name="Inheritance",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Glad you could make it, soldier. This is surreal. We're back in a place we knew long ago. Now it's in ruins. And it's crawling with all kinds of new wildlife. I guess it's true what they say. You can never go home again. Enough talking. Time to work. Emberthal wants this place locked down.",starts={{npcID=200403,x=0.55,y=0.372,mapID=2151}},ends={{npcID=200459,x=0.55,y=0.358,mapID=2151}},coords={x=0.55,y=0.372,source="quest_giver",mapID=2151},questType="standard"},
[72714] = {id=72714,name="An Interdisciplinary Approach",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The Dragonscale Expedition does not pose a threat to Sarkareth. The fact that Sarkareth and his followers would be so brazen as to attack them during their research... Ebyssian furrows his brow.> Save as many Expedition members as you can. The knowledge in these ruins is priceless if it can unlock the secrets of our past, but it is ultimately worthless when weighed against the value of single innocent life. I will meet you in the ruins above when I am done here.",starts={{npcID=199520,x=0.616,y=0.614,mapID=2151}},ends={{npcID=199177,x=0.588,y=0.704,mapID=2151}},coords={x=0.616,y=0.614,source="quest_giver",mapID=2151},questType="standard"},
[72715] = {id=72715,name="Keeping the Flame at Bay",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="It's not enough that Sarkareth kills our people, twists our heritage, and burns everything in his path. Now he seeks to pillage the creche of the Adamantine Vigil. Ebyssian and I will stay here while you push back the Sundered Flame. We'll meet you up top once the Expedition is secure.",starts={{npcID=199175,x=0.616,y=0.616,mapID=2151}},ends={{npcID=199521,x=0.588,y=0.704,mapID=2151}},coords={x=0.616,y=0.616,source="quest_giver",mapID=2151},questType="standard"},
[72717] = {id=72717,name="A Creche Divided",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="This place... I have not been here for a long time. Not since before I was a Scalecommander. It is a dark place, full of pain... and failure. This was where Neltharion tested those he considered most worthy of his attention. He poked and prodded us with powers we could not understand or control. Many of us were found... wanting. Perhaps Sarkareth brought me here to test me the same way our father tested us. Will you walk with me?",starts={{npcID=199538,x=0.742,y=0.368,mapID=2151}},ends={{npcID=199539,x=0.768,y=0.386,mapID=2151}},coords={x=0.742,y=0.368,source="quest_giver",mapID=2151},questType="standard"},
[72738] = {id=72738,name="The Way to an Otto's Heart",level=10,requiredLevel=10,faction="both",expansion=9,questType="standard"},
