[72874] = {id=72874,name="Secrets From Our Father",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,mapID=2133,description="Look closely, . You see this odd chunk of metal in the deepflayer muck? I have felt my head swimming since we arrived in these caverns. I thought it was just the ceaseless prattling of our whelp, Wrathion, but this object here may prove otherwise. I will continue my efforts to unlock this relic's secrets. Seek out similar pieces in the nearby caves. A dark theory is emerging, though we will need more information before I am willing to confirm it.",starts={{npcID=201589,x=0.606,y=0.4,mapID=2133}},ends={{npcID=201589,x=0.606,y=0.4,mapID=2133}},coords={x=0.606,y=0.4,source="quest_giver",mapID=2133},questType="standard"},
[72875] = {id=72875,name="Dragon Isles Supplies",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=193006,x=0.13,y=0.492,mapID=2024}},ends={{npcID=193006,x=0.13,y=0.492,mapID=2024}},coords={x=0.13,y=0.492,source="quest_giver",mapID=2024},questType="standard"},
[72933] = {id=72933,name="Rolling Out",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13647,mapID=2025,description="I remember having so much fun rolling these creatures up with my spells. Unfortunately, I fear these old bones will not let me move as quickly as I once did. I would love for you to give it a shot. Let me live vicariously through you! The more creatures you roll up, the bigger the ball becomes. The bigger the ball, the bigger the creature you can roll out. Speak to me and I shall give you my special arcane ball to roll up the creatures around here.",starts={{npcID=199961,x=0.638,y=0.122,mapID=2025}},ends={{npcID=199969,x=0.666,y=0.12,mapID=2025}},coords={x=0.638,y=0.122,source="quest_giver",mapID=2025},questType="standard"},
[72941] = {id=72941,name="Ancestral Advice",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="I have a message for my descendent. It is very important. I understand you are new to our language. I will try to speak in small, (100)-easy words. When you are ready to give your full attention, I will (90)-share my message.",starts={{npcID=199996,x=0.66,y=0.126,mapID=2024}},ends={{npcID=199267,x=0.66,y=0.126,mapID=2024}},coords={x=0.66,y=0.126,source="quest_giver",mapID=2024},questType="standard"},
[72944] = {id=72944,name="Sending Stone: Protest",level=70,requiredLevel=70,faction="alliance",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},questType="standard"},
[72945] = {id=72945,name="Our Path Ahead",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="I have a message for Chief Kranac Sagesnow . I believe that it is not too late to lead our people down a (80)-better path. However, if he chooses the wrong direction, I see only (90)-darkness ahead for our people. When you are ready, I will (80)-impart this message.",starts={{npcID=199300,x=0.67,y=0.13,mapID=2024}},ends={{npcID=199267,x=0.66,y=0.126,mapID=2024}},coords={x=0.67,y=0.13,source="quest_giver",mapID=2024},questType="standard"},
[72956] = {id=72956,name="More Doors To Open",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="There are still more vaults, but there aren't enough of us to explore them all. That's where you come in. Could you look for more keys? Then we can continue exploring the vaults. Tacha and I will stay here and work on documenting our earlier discoveries. That's tough work, but one of us has to do it. Okay, two of us. But it is a lot of work, I assure you.",starts={{npcID=200040,x=0.29,y=0.53,mapID=2151}},ends={{npcID=200040,x=0.29,y=0.53,mapID=2151}},coords={x=0.29,y=0.53,source="quest_giver",mapID=2151},questType="standard"},
[72966] = {id=72966,name="Where There's Smoke, There's Fire",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,mapID=2133,description="If you are finished indulging Ebyssian's associate, I would have us return to more pressing matters. Locating Fyrakk is still our primary mission. We cannot continue to delay it. I have discovered a massive caldera at the western edge of Zaralek. If Fyrakk is still here, then logic dictates that this volcanic area would be his hideout. Meet us there and we will proceed.",starts={{npcID=199849,x=0.566,y=0.568,mapID=2133}},ends={{npcID=200081,x=0.41,y=0.418,mapID=2133}},coords={x=0.566,y=0.568,source="quest_giver",mapID=2133},questType="standard"},
[72973] = {id=72973,name="Smells Like Loamm",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,mapID=2133,description="I smelled you weren't a bad sort from the start. A little sweaty, but not a bad sort. Consider this your personal invitation to Loamm, home of the niffen! Let's all meet just outside the entrance. That way I can give you and your pals the proper niffen welcome!",starts={{npcID=201584,x=0.57,y=0.382,mapID=2133}},ends={{npcID=204522,x=0.57,y=0.556,mapID=2133}},coords={x=0.57,y=0.382,source="quest_giver",mapID=2133},questType="standard"},
[72975] = {id=72975,name="The Land Beneath",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="I heard word you were aiding the green dragonflight, . I bring word from Ebyssian . The Life-Binder has news of the Incarnates, and she requests our presence at the Seat of the Aspects. The black dragonflight will await you there. I will move on ahead to continue tracking our foe.",starts={{npcID=201401,x=0.198,y=0.816,mapID=2023},{npcID=201401,x=0.514,y=0.352,mapID=2112}},ends={{npcID=201281,x=0.612,y=0.42,mapID=2112}},coords={x=0.198,y=0.816,source="quest_giver",mapID=2112},questType="standard"},
[72976] = {id=72976,name="A Crack in the World",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13862,mapID=2112,description="As you can see, Wrathion and Sabellian are also ready. If the Aspects have news of the Incarnates' actions, then the black dragonflight is prepared to answer the call. Come. They are eager to speak with us.",starts={{npcID=201281,x=0.612,y=0.42,mapID=2112}},ends={{npcID=201281,x=0.612,y=0.42,mapID=2112}},coords={x=0.612,y=0.42,source="quest_giver",mapID=2112},questType="standard"},
[72987] = {id=72987,name="Here We Go Again",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=14022,mapID=2133,description="I understand Alexstrasza's concerns. Shadowflame is a vile force that poses an indescribable threat to anyone who comes close to it, as we have personally witnessed. Unfortunately, Aberrus may contain even more threats. We need to continue to push forward. Before I left Zaralek Cavern , I made contact with soldiers stationed by Neltharion at the Obsidian Rest. Luckily for us, they remain loyal to the Black Dragonflight. Let us meet there.",starts={{npcID=203965,x=0.582,y=0.386,mapID=2112}},ends={{npcID=200046,x=0.5,y=0.276,mapID=2133}},coords={x=0.582,y=0.386,source="quest_giver",mapID=2133},questType="standard"},
[73012] = {id=73012,name="Hochenblume Harvest",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13844,mapID=2025,description="Every green dragon loves a leafy, crunchy snack. The plants that grow with Dream exposure are densely packed with nutrients, keeping the greens healthy and content. Hochenblume flowers are a sweet, delightful treat for young green dragons, and contain all the vitamins that a growing hatchling needs.",starts={{npcID=182082,x=0.13,y=0.572,mapID=2112}},ends={{npcID=182082,x=0.13,y=0.572,mapID=2112}},coords={x=0.13,y=0.572,source="quest_giver",mapID=2025},questType="standard"},
[73031] = {id=73031,name="Champion of the Winterpelt",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="Thank you for all that you have done, . It is all too easy to turn within and simply continue on as you always have. The Winterpelt will rejoin the world. We will return to the path our ancestors strayed from. And we will never forget your part in this. I have gathered the tribe and our new allies together to celebrate. Speak with me when you are ready to begin.",starts={{npcID=189394,x=0.66,y=0.106,mapID=2024}},ends={{npcID=189394,x=0.66,y=0.106,mapID=2024}},coords={x=0.66,y=0.106,source="quest_giver",mapID=2024},questType="standard"},
[73035] = {id=73035,name="Path of Trust",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="Radza sent me to find you and tell you to come to her. She set her incense burner out which means she's going to perform a ritual. That means whatever she wants is important. Radza's just west of here. I wouldn't keep her waiting!",starts={{npcID=199266,x=0.668,y=0.13,mapID=2024}},ends={{npcID=199267,x=0.66,y=0.126,mapID=2024}},coords={x=0.668,y=0.13,source="quest_giver",mapID=2024},questType="standard"},
[73064] = {id=73064,name="Spellwrought Snowman",level=30,requiredLevel=30,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[73071] = {id=73071,name="A Brew for the Ages",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Legends speak of an ale brewed by Neltharion himself. Yet this ale has been lost to the ages! If those stories are true, and doubtless they are, we may find the recipe within this vault. Ipfelkofer and I found three keys to this vault, so we decided to look around. Hopefully, our thirst for discovery will be quenched. If we found that recipe, imagine the excitement in the brewing community! We could even feature that ale at the next Brewfest! First round will be on me.",starts={{npcID=200456,x=0.308,y=0.566,mapID=2151}},ends={{npcID=200456,x=0.308,y=0.566,mapID=2151}},coords={x=0.308,y=0.566,source="quest_giver",mapID=2151},questType="standard"},
[73076] = {id=73076,name="Return to the Reach",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Long ago, the Reach was our training ground. Now it's time to return. The island may still hold secrets from our past. Scalecommander Emberthal has gone on ahead. She awaits the arrival of any who would lend us their aid. We'll need all the help we can get finding a foothold in the Reach. Safe travels.",starts={{npcID=201398,x=0.61,y=0.264,mapID=2112}},ends={{npcID=199201,x=0.346,y=0.576,mapID=2151},{npcID=199532,x=0.326,y=0.604,mapID=2151}},coords={x=0.61,y=0.264,source="quest_giver",mapID=2151},questType="standard"},
[73089] = {id=73089,name="What's Behind The Next Door",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="If we're going to keep exploring these vaults, we're going to need to open more doors! And that means we'll need more keys. See if you can find more keys around Forbidden Reach. Every door is another opportunity!",starts={{npcID=200041,x=0.292,y=0.53,mapID=2151}},ends={{npcID=200041,x=0.292,y=0.53,mapID=2151}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2151},questType="standard"},
[73092] = {id=73092,name="Something Like Family",level=36,requiredLevel=36,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Grab a bite! Scaralesh's Special! If you're a hungry dracthyr in need of cheer, this is the place! Between you and me, ? Our people have been through a lot lately. We need something to help us relax, and remind us that we've always got each other. I think a family meal could be just that. Rommen and I can handle the cooking. Will you bring plates to dracthyr who need a warm bite to eat?",starts={{npcID=201764,x=0.232,y=0.322,mapID=2112}},ends={{npcID=201764,x=0.232,y=0.322,mapID=2112}},coords={x=0.232,y=0.322,source="quest_giver",mapID=2112},questType="standard"},
[73094] = {id=73094,name="Aiding the Expedition",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Sarkareth must pay for his crimes. We cannot let any more dracthyr suffer because of Sarkareth's twisted ambitions. If the Sundered Flame is threatening the Dragonscale Expedition, then our allies need our help.",starts={{npcID=199531,x=0.55,y=0.358,mapID=2151}},ends={{npcID=199175,x=0.616,y=0.616,mapID=2151}},coords={x=0.55,y=0.358,source="quest_giver",mapID=2151},questType="standard"},
[73107] = {id=73107,name="Sending Stone: Initial Report",level=70,requiredLevel=70,faction="alliance",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},questType="standard"},
[73108] = {id=73108,name="Sending Stone: The Prisoner",level=70,requiredLevel=70,faction="alliance",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},questType="standard"},
[73109] = {id=73109,name="Receiving Stone: Final Warning",level=70,requiredLevel=70,faction="alliance",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},questType="standard"},
[73110] = {id=73110,name="Journal Entry: Experiments",level=70,requiredLevel=70,faction="horde",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},questType="standard"},
[73113] = {id=73113,name="Journal Entry: Relics",level=70,requiredLevel=70,faction="alliance",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},questType="standard"},
[73114] = {id=73114,name="Journal Entry: The Creches",level=70,requiredLevel=70,faction="alliance",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},questType="standard"},
[73115] = {id=73115,name="Journal Entry: Silence",level=70,requiredLevel=70,faction="alliance",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},questType="standard"},
[73137] = {id=73137,name="Chasing the Flame",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="\"He awaits you in the darkness\"? I know where Sarkareth is. I'll need your help holding him to account. If you want, you could stay here a while and pick through these ruins, but I think we have more pressing needs at hand. If you're willing to see this through to the end, then I need you to follow me. I'm going to Dragonskull Island.",starts={{npcID=199521,x=0.588,y=0.704,mapID=2151}},ends={{npcID=199538,x=0.742,y=0.368,mapID=2151}},coords={x=0.588,y=0.704,source="quest_giver",mapID=2151},questType="standard"},
[73139] = {id=73139,name="Deep Sea Supplies",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="We are accustomed to threats emerging from the sea. But there are some enemies that should never be allowed on our shores. In the east, naga are advancing on our beaches and coves. They've brought supplies with them. If we could reduce the local naga population and seize their supplies, our chances of survival here would increase. Here's the plan: take those supplies from their caches or their corpses, and slay their leader. Lives are on the line.",starts={{npcID=200558,x=0.344,y=0.586,mapID=2151}},ends={{npcID=200558,x=0.344,y=0.586,mapID=2151}},coords={x=0.344,y=0.586,source="quest_giver",mapID=2151},questType="standard"},
[73140] = {id=73140,name="Sunder the Crater",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The Primalists have moved into Stormsunder Crater. They're raising elementals and exploiting the land. They should be dealt with in a swift and decisive manner. Thin their ranks. Destroy their totems. Help us make the Forbidden Reach safe for the dracthyr, the tuskarr, and all the dispossessed who want to call it home again.",starts={{npcID=199204,x=0.354,y=0.586,mapID=2151}},ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},coords={x=0.354,y=0.586,source="quest_giver",mapID=2151},questType="standard"},
[73141] = {id=73141,name="Everburning Embers",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13642,mapID=2151,description="Warmth and heat are constant concerns for us at the homestead. We don't want to burn through everything we brought, and we don't like collecting driftwood on hostile shores. Too risky! The Primalists, though, carry some of their own fire with them. If you could slay some powerful fire Primalists, take their Everburning Embers , and bring those embers back here, we could make good use of them.",starts={{npcID=200558,x=0.344,y=0.586,mapID=2151}},ends={{npcID=200558,x=0.344,y=0.586,mapID=2151}},coords={x=0.344,y=0.586,source="quest_giver",mapID=2151},questType="group"},
[73142] = {id=73142,name="Busting Blues",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Malygos left behind forces to monitor us while we slept. He's gone, but his minions are still here, making life difficult for everyone. Scouts have seen them using Arcane Foci. I think we could make better use of them. Go collect some. Their security forces might put up a fight, but that won't be a problem for you, will it? Maybe they'll take the hint and leave.",starts={{npcID=199199,x=0.352,y=0.594,mapID=2151}},ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},coords={x=0.352,y=0.594,source="quest_giver",mapID=2151},questType="standard"},
[73155] = {id=73155,name="The Forgotten Ring",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,starts={{npcID=385952,x=0.298,y=0.572,mapID=2151}},ends={{npcID=200724,x=0.35,y=0.576,mapID=2151}},coords={x=0.298,y=0.572,source="quest_giver",mapID=2151},questType="standard"},
[73156] = {id=73156,name="Return to Viridia",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="I should entrust you to Viridia. She's working with the Healing Wings in Morqut Village to build a safe place for the dracthyr, the tuskarr, and our other allies in the Reach. We have a home here... and I... I have some thinking to do. I'm grateful that you walked beside me through this trial. This isn't over. But at least I know that the next time we face Sarkareth, we can count on you. Thank you.",starts={{npcID=199539,x=0.768,y=0.386,mapID=2151}},ends={{npcID=199201,x=0.346,y=0.576,mapID=2151}},coords={x=0.768,y=0.386,source="quest_giver",mapID=2151},questType="standard"},
[73157] = {id=73157,name="Wings of Mercy",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="With the lifting of the storms, we dispatched scout teams to explore the island. Several of our teams have not returned. We fear they may have fallen to unknown dangers. Can you search the island for them? Once you locate them, use the Mender's Signal to summon a medic.",starts={{npcID=199201,x=0.346,y=0.576,mapID=2151}},ends={{npcID=199201,x=0.346,y=0.576,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[73159] = {id=73159,name="Exploring Our Past",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="With your help, we can now delve deeper into the secrets of this land. Nearby lay the Zskera Vaults. Within these large underground chambers, Neltharion stored various treasures and forgotten research. Exploring these vaults would be most beneficial. Please travel with Tacha and Jeb and assist them as needed.",starts={{npcID=199201,x=0.346,y=0.576,mapID=2151}},ends={{npcID=200040,x=0.29,y=0.53,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[73160] = {id=73160,name="Helping Hand and Claw",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Members of the Dragonscale Expedition traveled here to help explore ruins on this island. Their efforts may help us uncover more details about our past. My scouts have spotted three of them shipwrecked on Sharpscale Coast. See if you can help them reach the village safely.",starts={{npcID=199201,x=0.346,y=0.576,mapID=2151}},ends={{npcID=200903,x=0.37,y=0.79,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[73171] = {id=73171,name="Gain New Look: Maiev",level=0,requiredLevel=0,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=384744,x=0.287,y=0.412,mapID=84},{npcID=384744,x=0.506,y=0.822,mapID=85},{npcID=384744,x=0.48,y=0.466,mapID=2112}},ends={{npcID=384744,x=0.287,y=0.412,mapID=84},{npcID=384744,x=0.506,y=0.822,mapID=85},{npcID=384744,x=0.48,y=0.466,mapID=2112}},coords={x=0.287,y=0.412,source="quest_giver",mapID=2112},questType="standard"},
