[73178] = {id=73178,name="Hands Off Our Booty!",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The Irontide Pirates have been stealing from dracthyr and tuskarr. They're taking anything and everything. It's all just booty to them! You should recover our stolen goods . Make them regret coming here.",starts={{npcID=199204,x=0.354,y=0.586,mapID=2151}},ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},coords={x=0.354,y=0.586,source="quest_giver",mapID=2151},questType="standard"},
[73179] = {id=73179,name="Soupocalypse Now!",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The Irontide pirates think they can sail in and take over the islands. They clearly have no idea who they are dealing with. Our Morqut friends will provide you with the transportation. We dracthyr will provide the... munitions. Fusethrian has been trying to learn to cook the tuskarr way with mixed results. Ask him for his more volatile attempts. We can get some safe disposal and run off these pirates in one go!",starts={{npcID=199199,x=0.352,y=0.594,mapID=2151}},ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},coords={x=0.352,y=0.594,source="quest_giver",mapID=2151},questType="standard"},
[73189] = {id=73189,name="Creche Cache",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="I'm glad you're here. Beetles infected our support creche, so we evacuated in a hurry. That meant leaving a lot of supplies behind. Now we've got a lot of injured explorers, and we could sure use those supplies. Can you help us? We need you to retrieve as many as you can. Just don't let the toxins get to you.",starts={{npcID=200727,x=0.348,y=0.574,mapID=2151}},ends={{npcID=200727,x=0.348,y=0.574,mapID=2151}},coords={x=0.348,y=0.574,source="quest_giver",mapID=2151},questType="standard"},
[73190] = {id=73190,name="Toxic Infestation",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The Healing Wings need access to our support creche, but it's still overflowing with an infestation of toxic beetles. I'm sure Viridia would appreciate it if we helped exterminate those pests.",starts={{npcID=199199,x=0.352,y=0.594,mapID=2151}},ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},coords={x=0.352,y=0.594,source="quest_giver",mapID=2151},questType="standard"},
[73191] = {id=73191,name="Snake Wrangling",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The same toxins that plague our Support Creche are seeping into migrating watersnakes. We need to relocate the snakes back to their original pools. If we don't, that invasive species is going to wreak havoc on the environment. I can loan you a friendly water elemental to help you transport the snakes. It's for our own safety as much as theirs.",starts={{npcID=201291,x=0.344,y=0.592,mapID=2151}},ends={{npcID=201291,x=0.344,y=0.592,mapID=2151}},coords={x=0.344,y=0.592,source="quest_giver",mapID=2151},questType="standard"},
[73194] = {id=73194,name="Up Close and Personal",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The great proto-dragons are some of the fiercest creatures to roam the Forbidden Reach . Taking them down isn't easy, but we have many weapons in our arsenal. Take this spear and harpoon. You'll need them. If you get caught in a proto-drake's maw, you'll need to fight tooth and claw with everything you've got to survive. It isn't easy, but I know you can do this.",starts={{npcID=199199,x=0.352,y=0.594,mapID=2151}},ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},coords={x=0.352,y=0.594,source="quest_giver",mapID=2151},questType="standard"},
[73226] = {id=73226,name="Dragonskull Shoal",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The fish could be biting better, don't you think? You know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it? Maybe you and your drake could give it a try?",starts={{npcID=200947,x=0.742,y=0.406,mapID=2151}},ends={{npcID=200947,x=0.742,y=0.406,mapID=2151}},coords={x=0.742,y=0.406,source="quest_giver",mapID=2151},questType="standard"},
[73371] = {id=73371,name="Gain New Look: Night Elf Huntress",level=0,requiredLevel=0,faction="both",expansion=9,zoneID=13862,mapID=2112,starts={{npcID=384744,x=0.287,y=0.412,mapID=84},{npcID=384744,x=0.506,y=0.822,mapID=85},{npcID=384744,x=0.48,y=0.466,mapID=2112}},ends={{npcID=384744,x=0.287,y=0.412,mapID=84},{npcID=384744,x=0.506,y=0.822,mapID=85},{npcID=384744,x=0.48,y=0.466,mapID=2112}},coords={x=0.287,y=0.412,source="quest_giver",mapID=2112},questType="standard"},
