[73398] = {id=73398,name="Too Far Forward",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Our forward forces pressed too aggressively into a Sundered Flame stronghold. Now they need help. We really need to send you in to extract them. Help them get out of there. You can use your own magic or these healing draughts from Viridia. And while you're there? Put some hurt on the Sundered Flame. They certainly deserve it.",starts={{npcID=199204,x=0.354,y=0.586,mapID=2151}},ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},coords={x=0.354,y=0.586,source="quest_giver",mapID=2151},questType="standard"},
[73550] = {id=73550,name="Honeyfreeze Mead",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="Right, so now that we've established somewhat friendlier relations and learned a wee bit of Winterpelt, it's about time tae make friends in the proper dwarf manner. What gesture of friendship is better than a stiff drink tae ward off tae cold? Both dwarves and furbolgs have a long history of brewin', so we can call it somethin' of a cultural exchange too! I saw some hearty lookin' bees a bit south of here. And where there's bees, there's honey. And where there's honey, there could be mead.",starts={{npcID=201065,x=0.668,y=0.126,mapID=2024}},ends={{npcID=201065,x=0.668,y=0.126,mapID=2024}},coords={x=0.668,y=0.126,source="quest_giver",mapID=2024},questType="standard"},
[73692] = {id=73692,name="Hive Maintenance",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="It wouldn't do tae steal a hive's honey without ensurin' they have enough food tae make it through the cold. Especially if we might want more down the line. Frostbell pollen's sticky stuff an' a wee bit fragile. But if ye run through some of the bloomin' plants, it'll be on ye like fleas on a kobold. Then, all ye have to do is bring it back tae a bee afore it blows away--they'll lick it right off ye! Tickles a bit too!",starts={{npcID=201065,x=0.668,y=0.126,mapID=2024}},ends={{npcID=201065,x=0.668,y=0.126,mapID=2024}},coords={x=0.668,y=0.126,source="quest_giver",mapID=2024},questType="standard"},
[73694] = {id=73694,name="Stuck in Stasis",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13642,mapID=2151,description="When the first dracthyr awakened from millennia of slumber, we left the Forbidden Reach for the Dragon Isles. Yet not all of the dracthyr are free. Some are still in stasis, hidden deep within their creches. We need your help. Travel to Froststone Vault. See if you can find more of our friends. One of my Healing Wings would be glad to accompany you. Choose someone who best suits your need. It is time for all dracthyr to rejoin the world as we have.",starts={{npcID=199201,x=0.346,y=0.576,mapID=2151}},ends={{npcID=199201,x=0.346,y=0.576,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[73703] = {id=73703,name="A Summon to Orgrimmar",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=1637,mapID=85,description=", Eitrigg has requested your presence in Grommash Hold. He seemed like he had much to tell you.",ends={{npcID=3144,x=0.49,y=0.722,mapID=85}},questType="standard"},
[73704] = {id=73704,name="Local Flavors",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,description="Now that we have the base o' the brew figured out, we need tae add the spice. Put that rudimentary Winterpelt I taught ye tae use and ask around for local ingredients tae blend into the flavor profile. Try talkin' with Kazzi. From what I gather she's somethin' of a trader. The finished brew will be a mix of dwarven and Winterpelt traditions which seems appropriate for the circumstances. An' if we're lucky, it won't taste half bad!",starts={{npcID=201065,x=0.668,y=0.126,mapID=2024}},ends={{npcID=201065,x=0.668,y=0.126,mapID=2024}},coords={x=0.668,y=0.126,source="quest_giver",mapID=2024},questType="standard"},
[73715] = {id=73715,name="Driftwood Derby",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="One of the challenges of any new village is finding enough raw building materials. Fortunately, the ocean often brings us exactly what we need. Take my boat and sail around the island. Along the way, you can collect driftwood in nets. But be wary. You may attract some unwanted attention!",starts={{npcID=200558,x=0.344,y=0.586,mapID=2151}},ends={{npcID=200558,x=0.344,y=0.586,mapID=2151}},coords={x=0.344,y=0.586,source="quest_giver",mapID=2151},questType="standard"},
[73716] = {id=73716,name="Aylaag Elder",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=201129,x=0.442,y=0.638,mapID=2022}},ends={{npcID=201129,x=0.442,y=0.638,mapID=2022}},coords={x=0.442,y=0.638,source="quest_giver",mapID=2022},questType="standard"},
[73717] = {id=73717,name="Ohn'ir Elder",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13645,mapID=2023,starts={{npcID=201132,x=0.584,y=0.314,mapID=2023}},ends={{npcID=201132,x=0.584,y=0.314,mapID=2023}},coords={x=0.584,y=0.314,source="quest_giver",mapID=2023},questType="standard"},
[73848] = {id=73848,name="Iskaara Elder Shomkol",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13644,mapID=2022,starts={{npcID=201137,x=0.466,y=0.312,mapID=2022}},ends={{npcID=201137,x=0.466,y=0.312,mapID=2022}},coords={x=0.466,y=0.312,source="quest_giver",mapID=2022},questType="standard"},
[73858] = {id=73858,name="Iskaara Elder Nemaglek",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=201139,x=0.128,y=0.49,mapID=2024}},ends={{npcID=201139,x=0.128,y=0.49,mapID=2024}},coords={x=0.128,y=0.49,source="quest_giver",mapID=2024},questType="standard"},
[73859] = {id=73859,name="Iskaara Elder Sik'ek",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13647,mapID=2025,starts={{npcID=201140,x=0.548,y=0.434,mapID=2025}},ends={{npcID=201140,x=0.548,y=0.434,mapID=2025}},coords={x=0.548,y=0.434,source="quest_giver",mapID=2025},questType="standard"},
[73860] = {id=73860,name="Elder Dekidig",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13646,mapID=2024,starts={{npcID=201141,x=0.674,y=0.494,mapID=2024}},ends={{npcID=201141,x=0.674,y=0.494,mapID=2024}},coords={x=0.674,y=0.494,source="quest_giver",mapID=2024},questType="standard"},
[73861] = {id=73861,name="Elder Razlok",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13647,mapID=2025,starts={{npcID=201143,x=0.5,y=0.664,mapID=2025}},ends={{npcID=201143,x=0.5,y=0.664,mapID=2025}},coords={x=0.5,y=0.664,source="quest_giver",mapID=2025},questType="standard"},
[74117] = {id=74117,name="Rare Prey",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13642,mapID=2151,description="Rare and dangerous creatures lurk around the creches of the Forbidden Reach . If you and your allies want to stay safe, you should hunt down these threats.",starts={{npcID=200564,x=0.34,y=0.598,mapID=2151}},ends={{npcID=200564,x=0.34,y=0.598,mapID=2151}},coords={x=0.34,y=0.598,source="quest_giver",mapID=2151},questType="standard"},
[74118] = {id=74118,name="Spelunking the Den",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Did you have a chance to visit the Skyfox Den? A very exciting place, from what I've heard. Expedition's spelunkers started surveying the cave and even installed a few grappling hooks on the ceiling, but they were scared away by violent slyverns. Can you do me a favor? Get inside the Skyfox Den, grab the abandoned gear, and check the ceiling for any hidden crevices. Who knows what could be hidden inside?",starts={{npcID=200566,x=0.342,y=0.598,mapID=2151}},ends={{npcID=200566,x=0.342,y=0.598,mapID=2151}},coords={x=0.342,y=0.598,source="quest_giver",mapID=2151},questType="standard"},
[74119] = {id=74119,name="Angler's Challenge",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots to cast a line. Why don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.",starts={{npcID=200562,x=0.342,y=0.6,mapID=2151}},ends={{npcID=200562,x=0.342,y=0.6,mapID=2151}},coords={x=0.342,y=0.6,source="quest_giver",mapID=2151},questType="standard"},
[74282] = {id=74282,name="Authentic Authorization",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course! If I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans! If you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!",starts={{npcID=201180,x=0.292,y=0.528,mapID=2151}},ends={{npcID=201180,x=0.292,y=0.528,mapID=2151}},coords={x=0.292,y=0.528,source="quest_giver",mapID=2151},questType="standard"},
[74293] = {id=74293,name="Not Forgotten",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Viridia is confident that more dracthyr may slumber in these chambers, long forgotten amongst Neltharion's relics.",starts={{npcID=201240,x=0.288,y=0.522,mapID=2151}},ends={{npcID=199201,x=0.346,y=0.576,mapID=2151}},coords={x=0.288,y=0.522,source="quest_giver",mapID=2151},questType="standard"},
[74294] = {id=74294,name="The Keys You Need",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Can I trust you? These are the only keys we have. If we lose them, we can't open any locked doors. Here. Take them. Use them on the doors within this chamber. You look like a hero. Be bold! Throw those doors wide! You'll find glory or... um... something that is not glory but is still amazing! Just don't die. We might find more, but we'll have to search the island to find them.",starts={{npcID=200041,x=0.292,y=0.53,mapID=2151}},ends={{npcID=200041,x=0.292,y=0.53,mapID=2151}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2151},questType="standard"},
[74300] = {id=74300,name="Tectonus",level=70,requiredLevel=70,faction="none",expansion=9,zoneID=14433,mapID=2151,questType="standard"},
[74355] = {id=74355,name="Primordial Embellishment",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="How remarkable! You can affix such a variety of special gems to enhance its power! You should journey back into the Zskera Vaults and locate a Primordial Jeweler's Kit . Yes, that's what you'll need. Crafting gems of this type requires specialized tools. Once we have them, we can fully explore the ring's power! The mind reels with limitless possibilities...",starts={{npcID=200724,x=0.35,y=0.576,mapID=2151}},ends={{npcID=200724,x=0.35,y=0.576,mapID=2151}},coords={x=0.35,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[74359] = {id=74359,name="Plunder Siege",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="We're not the only ones to have noticed the storms abating over the Forbidden Reach . Other interested parties have arrived too, looting everything they can and storing their spoils in chests. If they use Neltharion's old hoard chests, they're in for a surprise when the chests' enchantments lock them out. We'll need to clear out surrounding looters to break the chests' enchantments. See if you can recover a stolen item, specifically my old journal. It's nowhere to be found.",starts={{npcID=200010,x=0.346,y=0.576,mapID=2151}},ends={{npcID=200010,x=0.346,y=0.576,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[74374] = {id=74374,name="An Important Heirloom",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="I can guide you in crafting your offering to the ancestors, but you will need two things: First, you need to know the basics! Arugi here can teach you how to cook if you don't already know. Second, I need my old cookbook. We're going to make something truly special, a fusion of old Draenor and Azeroth, and I'm going to need it for reference. Go fetch my book from the inn, and we can get started.",starts={{npcID=199383,x=0.508,y=0.428,mapID=1}},ends={{npcID=199383,x=0.508,y=0.428,mapID=1}},coords={x=0.508,y=0.428,source="quest_giver",mapID=1},questType="standard"},
[74376] = {id=74376,name="Coalesced Storm Remnants",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13992,mapID=2085,description="The Primalist Researchers in the area will be interested in this for further study.",ends={{npcID=199425,x=0.612,y=0.47,mapID=2085}},questType="standard"},
[74379] = {id=74379,name="Still Within Reach",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="While we dracthyr were kept in stasis, the Spellsworn, ancient servants of Malygos the Spellweaver, were our wardens. However, despite being slain years ago, the late Aspect's forces are still loyal to him and his lasting directive to keep this island contained. They present a danger to any dracthyr still lost, wounded, or otherwise unaccounted for. Scouts have reported the sighting of a rather large Spellsworn brute hunting for escaped dracthyr. This deadly pursuer must be dealt with.",starts={{npcID=200559,x=0.356,y=0.594,mapID=2151}},ends={{npcID=200559,x=0.356,y=0.594,mapID=2151}},coords={x=0.356,y=0.594,source="quest_giver",mapID=2151},questType="group"},
[74381] = {id=74381,name="Hidden Legacies",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Raszageth and her storms are gone, but our troubles are far from over. The way to the Reach is clear again, and some of our allies have returned to establish a base camp. However, Sarkareth and the Sundered Flame have begun making their way there as well. We need to secure the island. We would appreciate your aid.",starts={{npcID=201398,x=0.61,y=0.264,mapID=2112}},ends={{npcID=201398,x=0.61,y=0.264,mapID=2112}},coords={x=0.61,y=0.264,source="quest_giver",mapID=2112},questType="standard"},
[74382] = {id=74382,name="Community Feast",level=10,requiredLevel=10,faction="none",expansion=9,zoneID=13646,mapID=2024,questType="standard"},
[74389] = {id=74389,name="Filming the Caldera",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The arthropods in Caldera of the Menders are truly vicious. One of our gyrocopters went missing there! Our expedition sent a unmanned surveillance aircraft there, but it hasn't returned. Can you find the gyrocopter? You could use it to capture the Caldera's wildlife on camera?",starts={{npcID=200566,x=0.342,y=0.598,mapID=2151}},ends={{npcID=200566,x=0.342,y=0.598,mapID=2151}},coords={x=0.342,y=0.598,source="quest_giver",mapID=2151},questType="standard"},
[74390] = {id=74390,name="Brutal Prey",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13642,mapID=2151,description="This land is crawling with opportunities for a skilled hunter. We want you to join the hunt. Some threats are feral. Dare I say it, some are greatest threats are sentient and malevolent. If we all work together, we can make the Reach a safe haven, as it used to be.",starts={{npcID=200564,x=0.34,y=0.598,mapID=2151}},ends={{npcID=200564,x=0.34,y=0.598,mapID=2151}},coords={x=0.34,y=0.598,source="quest_giver",mapID=2151},questType="standard"},
[74391] = {id=74391,name="Harpooner's Challenge",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14022,mapID=2133,description="Say, have you noticed how good the fishing is around here? Dragonskull Island seems like it would have some great spots. Why don't you go there and catch something for dinner? Be mindful, though. We still need to set some of our catch aside for later.",starts={{npcID=200562,x=0.342,y=0.6,mapID=2151}},ends={{npcID=200562,x=0.342,y=0.6,mapID=2151}},coords={x=0.342,y=0.6,source="quest_giver",mapID=2133},questType="standard"},
[74415] = {id=74415,name="A Worthy Offering",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=14,mapID=1,description="Now that we have everything on the list, you just have to put it all together, right? How hard could it be? Umm... I'm going to let you handle it, though. I'll watch.",ends={{npcID=199148,x=0.522,y=0.43,mapID=1}},questType="standard"},
[74433] = {id=74433,name="Returning the Blade",level=30,requiredLevel=30,faction="both",expansion=9,zoneID=13646,mapID=2024,ends={{npcID=200206,x=0.668,y=0.13,mapID=2024}},questType="standard"},
[74440] = {id=74440,name="Windseeker Avash",level=20,requiredLevel=20,faction="none",expansion=9,zoneID=13645,mapID=2023,questType="standard"},
[74442] = {id=74442,name="One Dragon's Junk...",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Greetings! I am looking for items of power from my flight's past. We have a history of great warriors and battle prowess, and I want to recover items that will help us reach that again. I heard you found these vaults. If you see anything of interest inside, could you show it to me?",starts={{npcID=201517,x=0.292,y=0.53,mapID=2151}},ends={{npcID=201517,x=0.292,y=0.53,mapID=2151}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2151},questType="standard"},
[74443] = {id=74443,name="Is Another Dragon's Treasure?",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="I must admit, I am out of my depth here. It is of black dragon make. The decoration on the pommel matches, but I have no idea what it is. Which I suppose is the point. I have heard you have travelled the Isles. Do you have any recommendations on who to talk to?",starts={{npcID=201517,x=0.292,y=0.53,mapID=2151}},ends={{npcID=201517,x=0.292,y=0.53,mapID=2151}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2151},questType="standard"},
[74447] = {id=74447,name="Verbal Archaeology",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Where should we meet this Veritistrasz of yours? Ruby Lifeshrine? Are you sure this is not an attempt to introduce me to Alexstrasza? No? Well then! I shall meet you at the Ruby Lifeshrine!",starts={{npcID=201517,x=0.292,y=0.53,mapID=2151}},ends={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2023},questType="standard"},
[74488] = {id=74488,name="Runaway Rusziona",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Black whelps have the agility of a rock, but they try to make up for it with the most impressive top speed. Try to take it easy around those corners! : Dash forward. : Stops forward movement. : Restores all Vigor. Must be grounded.",starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},ends={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[74489] = {id=74489,name="Zhoomsa",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Bronze whelps can be careless when trying to win, so be careful with the timeways! : Transform into an adult and gain improved speed. : Restore 1 Vigor until all Vigor has been recovered. : Resets cooldowns.",starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},ends={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[74490] = {id=74490,name="Zaleth on the Go",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Blue whelps will try to skip ahead where they can, but be careful blinking through rings! : Blink forward and dash. : Increases forward acceleration. : Consumes Arcane Acceleration and restores Vigor.",starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},ends={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[74491] = {id=74491,name="Pole Position Posidriss",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Green whelps have an affinity for short naps and bursts of speed, so do your best to keep pace. : Fly up then restore 1 Vigor. : Adds 5 sec to Winds of Life's duration. : Anytime you restore Vigor, dash forward.",starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},ends={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[74492] = {id=74492,name="Blistering Belastrasza",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Red whelps can be a little out of control, so best of luck! : Consumes all Vigor over time. : Restore all Vigor, boosting forward each time. : Consumes Crimson Flight, resets cooldowns.",starts={{npcID=201443,x=0.138,y=0.59,mapID=2112}},ends={{npcID=201443,x=0.138,y=0.59,mapID=2112}},coords={x=0.138,y=0.59,source="quest_giver",mapID=2112},questType="standard"},
[74493] = {id=74493,name="Second Time Is The Charm",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Voraxian bounces the Odd Round Object in his hands a few times.> Hmm, it lands in the hand well, like it was made for this. Let us talk to Veritistrasz and see if he knows more.",starts={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},ends={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},coords={x=0.578,y=0.67,source="quest_giver",mapID=2023},questType="standard"},
[74494] = {id=74494,name="A Scale for a Scale",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,mapID=2133,description="The elder waking was a threat, certainly. But there is one more mission I must complete before we depart, lest we lose our only chance to complete it at all. However different the Zaqali tribe may be from the Qalashi, they are still dragonslayers. Their implements of war are no less deadly to our kind. I need a spear on par with the one we saw at the elder's side. Find the largest one you can and deliver it to me.",starts={{npcID=201647,x=0.283,y=0.51,mapID=2133}},ends={{npcID=199952,x=0.296,y=0.496,mapID=2133}},coords={x=0.283,y=0.51,source="quest_giver",mapID=2133},questType="standard"},
[74502] = {id=74502,name="Complimentary Gift",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,starts={{npcID=201714,x=0.282,y=0.568,mapID=2151}},ends={{npcID=201714,x=0.282,y=0.568,mapID=2151}},coords={x=0.282,y=0.568,source="quest_giver",mapID=2151},questType="standard"},
[74503] = {id=74503,name="Another Gift",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,starts={{npcID=201714,x=0.282,y=0.568,mapID=2151}},ends={{npcID=201714,x=0.282,y=0.568,mapID=2151}},coords={x=0.282,y=0.568,source="quest_giver",mapID=2151},questType="standard"},
[74519] = {id=74519,name="Good for Goo",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,mapID=2133,description="Every snail trainer knows that it's all about the goo. The slime. The mucus. That's how you turn a speedy snail into a champion. Slick could use a good slather. Go out and collect some goo from the local slime trails to slick him up. Heh.",starts={{npcID=201752,x=0.442,y=0.8,mapID=2133}},ends={{npcID=201752,x=0.442,y=0.8,mapID=2133}},coords={x=0.442,y=0.8,source="quest_giver",mapID=2133},questType="standard"},
[74581] = {id=74581,name="The Long Knives",level=50,requiredLevel=50,faction="horde",expansion=9,zoneID=6451,mapID=1,starts={{npcID=199151,x=0.54,y=0.426,mapID=1},{npcID=199152,x=0.54,y=0.422,mapID=1},{npcID=199154,x=0.542,y=0.424,mapID=1},{npcID=199156,x=0.54,y=0.426,mapID=1},{npcID=199173,x=0.54,y=0.424,mapID=1},{npcID=200616,x=0.522,y=0.428,mapID=1}},ends={{npcID=10176,x=0.432,y=0.688,mapID=1},{npcID=10176,x=0.452,y=0.686,mapID=1}},coords={x=0.54,y=0.426,source="quest_giver",mapID=1},questType="standard"},
[74769] = {id=74769,name="Stemming the Irontide",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Unfortunately, we are not the only ones who took notice of opportunities in the Reach. Our scouts have sent word of pirate vessels moored offshore. The first longboats have apparently come ashore on our northeastern beaches. Our history is not theirs to plunder. If you come across these pirates, send them swimming back to their little boats.",starts={{npcID=199201,x=0.346,y=0.576,mapID=2151}},ends={{npcID=199201,x=0.346,y=0.576,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[74771] = {id=74771,name="Key Hunting",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="My pockets are empty. I have no more vault keys! See if you can find any Zskera Keys, and Jeb and I will see what we can find. If we pool our keys, we can open a lot of doors.",starts={{npcID=200041,x=0.292,y=0.53,mapID=2151}},ends={{npcID=200041,x=0.292,y=0.53,mapID=2151}},coords={x=0.292,y=0.53,source="quest_giver",mapID=2151},questType="standard"},
[74795] = {id=74795,name="An Odd Round Object",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Voraxian .>",ends={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},questType="standard"},
[74796] = {id=74796,name="A Dusty Vase",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Voraxian is interested in.>",ends={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},questType="standard"},
[74847] = {id=74847,name="Emberthal Awaits",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="We are by no means ready to relax, but at least our encampment here is stable... for the time being. I should be able to handle the rest of our operation from here. Emberthal arrived while you were in the field. She and her allies are surveying the area from the cliffs above. It would be wise to check in with her, I think. We would not want her to attempt taking the Reach alone.",starts={{npcID=199201,x=0.346,y=0.576,mapID=2151}},ends={{npcID=199532,x=0.326,y=0.604,mapID=2151}},coords={x=0.346,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[74861] = {id=74861,name="An Unfriendly Confrontation",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,mapID=2133,description="I knew I recognized that drogbar's voice. He probably took Persii. I bet he knows where she is! Please, $p, you gotta track down that big bully. Do whatever it takes to get Persii back!",starts={{npcID=202597,x=0.51,y=0.74,mapID=2133}},ends={{npcID=202600,x=0.504,y=0.764,mapID=2133}},coords={x=0.51,y=0.74,source="quest_giver",mapID=2133},questType="standard"},
[74866] = {id=74866,name="Journal Entry: Experiments",level=70,requiredLevel=70,faction="alliance",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199204,x=0.354,y=0.586,mapID=2151}},questType="standard"},
[74869] = {id=74869,name="Primordial Answers",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Revelations await us within this vault. Perhaps we'll find a way to protect ourselves against Primalist magic. The elementals hiding in these vaults are wild, ancient, and free of Primalist control. Perhaps they hold the secret to helping the elementals on the surface. I have an idea. We'll need four primordial cores. Then we can construct a talisman that can purify and remove the influence of Primalist control from the elementals outside. If you help us, I will share what we have found here.",starts={{npcID=202627,x=0.288,y=0.576,mapID=2151}},ends={{npcID=202627,x=0.288,y=0.576,mapID=2151}},coords={x=0.288,y=0.576,source="quest_giver",mapID=2151},questType="standard"},
[74880] = {id=74880,name="Journal Entry: Relics",level=70,requiredLevel=70,faction="horde",expansion=9,zoneID=14433,mapID=2151,ends={{npcID=199199,x=0.352,y=0.594,mapID=2151}},questType="standard"},
