[74908] = {id=74908,name="New Adventures",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Cataloger Daela is here to investigate places of wonder and mystery. Skyfox Den and Caldera of the Menders look especially promising. Completing her quests will unlock her Envoy Tasks today. You will be able to unlock other factions' Envoy Tasks tomorrow.",ends={{npcID=200566,x=0.342,y=0.598,mapID=2151}},questType="standard"},
[74909] = {id=74909,name="New Catches",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Turik is here to investigate the riches of the sea across the Forbidden Reach on behalf of the Iskaara Tuskarr. Completing this quest will unlock his Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.",ends={{npcID=200562,x=0.342,y=0.6,mapID=2151}},questType="standard"},
[74910] = {id=74910,name="New Foes",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Storykeeper Ashekh is here to scout for enemies of the Maruuk. Completing this quest will unlock her Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.",ends={{npcID=200564,x=0.34,y=0.598,mapID=2151}},questType="standard"},
[74911] = {id=74911,name="New Horizons",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Kraxxus represents the strength of Valdrakken Accord here on Forbidden Reach. Completing this quest will unlock her Envoy tasks today. You will be able to unlock other factions' Envoy tasks tomorrow.",ends={{npcID=200563,x=0.34,y=0.598,mapID=2151}},questType="standard"},
[74946] = {id=74946,name="A Place of Refuge",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Our next priority is to catch up with the others who fled during Bovan's stand. Hopefully, Bovan and the other braves have regrouped with them. This Tomul says the most likely place the tauren would seek refuge is an abandoned village to the southeast. While her reasoning is sound, this is also the perfect location for a trap. , I know you vouch for her, so I will give her the benefit of the doubt. Let us hope your trust in her is not misplaced.",starts={{npcID=202707,x=0.694,y=0.476,mapID=2023}},ends={{npcID=200492,x=0.732,y=0.55,mapID=2023}},coords={x=0.694,y=0.476,source="quest_giver",mapID=2023},questType="standard"},
[74983] = {id=74983,name="Authentic Authorization",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course! If I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans! If you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!",starts={{npcID=201180,x=0.292,y=0.528,mapID=2151}},ends={{npcID=201180,x=0.292,y=0.528,mapID=2151}},coords={x=0.292,y=0.528,source="quest_giver",mapID=2151},questType="standard"},
[74984] = {id=74984,name="Authentic Authorization",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="The importance of this expedition can not be understated. I assure you, all who participate will have a place in history... along with me, of course! If I can make one remarkable discovery, my scholarly legacy will be assured! But what will we find? A copy of Neltharion's signature? One of his personal letters? Can't wait to find something to share with my fans. Also, I'll have more fans! If you would be so kind as to find me something memorable, I'll offer you suitable remuneration! I can pay!",starts={{npcID=201180,x=0.292,y=0.528,mapID=2151}},ends={{npcID=201180,x=0.292,y=0.528,mapID=2151}},coords={x=0.292,y=0.528,source="quest_giver",mapID=2151},questType="standard"},
[74994] = {id=74994,name="Hraxian's Unbreakable Will",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14022,mapID=2133,starts={{npcID=200298,x=0.402,y=0.684,mapID=2133}},ends={{npcID=200298,x=0.402,y=0.684,mapID=2133}},coords={x=0.402,y=0.684,source="quest_giver",mapID=2133},questType="standard"},
[74996] = {id=74996,name="A Difficult Legacy",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="Let us talk to Veritistrasz about this vase, $p. I want to temper your expectations though. It is just a vase, but you never know. It could be exciting. Maybe it could point us to a cache of weapons?",starts={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},ends={{npcID=201564,x=0.578,y=0.67,mapID=2022},{npcID=201564,x=0.856,y=0.35,mapID=2023}},coords={x=0.578,y=0.67,source="quest_giver",mapID=2023},questType="standard"},
[75258] = {id=75258,name="A Final Word",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13645,mapID=2023,description="I have sent a message to Mayla in Valdrakken, relaying what has happened here. I suspect she will be relieved to hear from me... and in knowing she was right to send you. Before you leave, I would like to speak with you a moment.",starts={{npcID=201566,x=0.726,y=0.56,mapID=2023}},ends={{npcID=201566,x=0.726,y=0.56,mapID=2023}},coords={x=0.726,y=0.56,source="quest_giver",mapID=2023},questType="standard"},
