[76217] = {id=76217,name="Living History",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13642,mapID=2151,description="My name is Nirobin . It is worth remembering, as I am a genius in the field of arcane codicology! Quite an accolade, if I say so myself... and I do say so! I've spent countless hours fusing blue and bronze dragon magic to investigate history like never before. Today, you and I will experience the results of my effort! Let's start by using my instruments on a fabulously preserved goblet uncovered from the Forbidden Reach.",starts={{npcID=205967,x=0.584,y=0.368,mapID=2025}},ends={{npcID=205967,x=0.584,y=0.368,mapID=2025}},coords={x=0.584,y=0.368,source="quest_giver",mapID=2151},questType="standard"},
